(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-fast-and-memory-efficient-video-diff-2024"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-1\">一 · 开场：一个正在被 SLO 撕扯的在线视频生成服务</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-2\">二 · 旧方案的基本形状：整段潜变量、整段采样、整段解码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-3\">三 · 痛点一：峰值显存的加法结构，把可部署档位锁死</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-4\">四 · 痛点二：带宽被多步采样反复征收，算力反而闲置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-5\">五 · 痛点三：长视频分块与重叠的重复计算，以及批调度与流式输出的矛盾</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-6\">六 · 为什么非改不可：Blackwell 档位把旧方案的余量吃干净了</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-7\">七 · 在线短视频生成服务的显存墙：块间重叠的重复计算与批调度抖动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-8\">八 · 请求形态：块数、重叠与并发三轴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-9\">九 · 输入长度分布与长尾</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-10\">十 · 批大小与 SLO 的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-11\">十一 · 负载如何反向限制方案</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-12\">十二 · 可核查的测量口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-13\">十三 · 失败模式的负载侧根源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-14\">十四 · 块粒度负载：流式管线的容量边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-15\">十五 · 从块级激活到算子选型：精度为什么是流式推理的第一性约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-16\">十六 · 核心 kernel 的分解：时空注意力、流匹配步与 VAE 解码的精度分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-17\">十七 · 累加精度与误差传播：FP32 累加器为什么不能省</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-18\">十八 · Blackwell 特性如何改变精度决策：tcgen05、TMEM 与 2-SM MMA</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-19\">十九 · NVFP4 的边界：块级缩放与流式管线的适配条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-20\">二十 · 精度回退与调度器的联动：把数值格式当作可调档位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-21\">二十一 · 显存账本的三个户头：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-22\">二十二 · KV 的分页、压缩与复用：省的是带宽，不是容量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-23\">二十三 · 复用与卸载：把常数项挪出 HBM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-24\">二十四 · 带宽瓶颈在哪：HBM3e 容量怎么算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-25\">二十五 · 一个可复算的显存预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-26\">二十六 · 调度器与显存水位的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-27\">二十七 · 流式账本的边界：重叠税、水位回退与跨档位可移植性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-28\">二十八 · 块粒度连续批处理：把“批”下沉到时间块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-29\">二十九 · Chunked prefill 的变体：预填与采样步的交错</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-30\">三十 · 优先级与抢占：SLO 驱动的块级调度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-31\">三十一 · 分离式预填/解码在视频扩散里的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-32\">三十二 · 尾延迟的压缩：重叠窗口与批大小的联合定档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-33\">三十三 · 块粒度调度在并发下的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-34\">三十四 · 切分维度与流式块的对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-35\">三十五 · NVLink 5 与 NVSwitch：域内通信的物理上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-36\">三十六 · NIXL 传输：把缓存搬运从计算路径上摘出去</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-37\">三十七 · 通信何时成为瓶颈：三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-38\">三十八 · 把通信代价纳入块调度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-39\">三十九 · 块粒度流水线在并行切分下的通信边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-40\">四十 · 精度塌陷：从“格式合法”到“数值不可用”的分界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-41\">四十一 · OOM 的真实来源：峰值公式里的隐藏项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-42\">四十二 · 批抖动与尾延迟：块粒度调度的固有代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-43\">四十三 · 静默降级：没有报错的性能与质量滑坡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-44\">四十四 · 监控面与定位顺序：从水位到块边界的排查链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-45\">四十五 · 回滚的工程边界：可移植性与跨档位重验</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-46\">四十六 · 流式管线的失效边界：从块级水位到静默降级的诊断路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-47\">四十七 · 基准口径的三层结构：模型、硬件档位、负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-48\">四十八 · 指标定义：TTFT、TPOT、吞吐、显存、功耗各自测什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-49\">四十九 · 哪些提升不可比：五类常见的错位比较</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-50\">五十 · 消融怎么读：块大小、重叠窗口、缓存复用三旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-51\">五十一 · 面向容量规划的读法：把机制结论转成可执行判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-52\">五十二 · 迁移到非 DiT 主干：缓存契约先于算子移植</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-53\">五十三 · 精度与算子：跨档位迁移要重做验证矩阵</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-54\">五十四 · 领域迁移：长时序、强交互、实时闭环三类场景的适配度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-55\">五十五 · 规模上限：块数与复用链长度的双重约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-56\">五十六 · 不适用的边界与回退路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fast-and-memory-efficient-video-diff-2024-sec-57\">五十七 · 迁移边界：什么能搬、什么必须重算、上限卡在哪</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:551px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 551.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入后按时间块切分视频潜变量，确定块大小与重叠窗口。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">逐块执行时空注意力与流匹配采样步，跨块复用缓存中的键值与中间特征。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">采样完成后按块进行 VAE 解码，流式输出视频帧并释放已用缓存。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">调度器根据显存水位调整批大小与块重叠，维持吞吐与 SLO。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">监控峰值显存与块间等待时间，异常时回退到更小分块或更低精度。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-1\">一 · 开场：一个正在被 SLO 撕扯的在线视频生成服务</h3>\n<p>设想一个面向内容平台的在线文生视频服务：用户提交一段文本，期望在数秒到十几秒内拿到一段数秒钟、分辨率可用的短视频。请求不是均匀到达的，晚高峰的并发是平峰的若干倍，而 SLA 写死了首帧时间与整段视频的完成时间。工程团队把视频扩散模型部署在 GB200 NVL72 的一个机柜里，模型本身跑得动，单请求也能出片，但一旦并发上来，问题立刻显形：显存水位随并发线性抬升，采样步数乘以时空注意力的激活占用把每张卡的余量吃干，调度器被迫在“多接一个请求”和“别 OOM”之间反复横跳；同时长视频被切成块串行推进，块与块之间的等待让尾延迟抖动，SLO 的达标率随负载上升而塌陷。这不是模型能力问题，而是推理栈的组织方式问题——旧方案把视频扩散当成“一次性的大张量前向”来处理，而视频扩散的真实形态是“多步采样 × 时空注意力 × 长序列潜变量 × 昂贵的 VAE 解码”的复合体。</p>\n<p>本部分只做一件事：把这篇论文出现之前的推理栈主流做法摊开，指出它在显存、带宽、时延三个维度上的具体代价，以及为什么这些代价在 Blackwell 档位上不是“调调参数”能解决的。分块流式采样、跨块缓存复用、按块 VAE 解码这些机制本身留给后续部分展开，这里只交代它们要替代的是什么。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-2\">二 · 旧方案的基本形状：整段潜变量、整段采样、整段解码</h3>\n<p>论文之前，视频扩散推理栈的主流做法可以概括为“三段式整段处理”。第一段，文本编码与潜变量初始化：把整段视频的潜变量一次性物化到显存里，形状大致是 <span class=\"formula\">$$[B, C, T, H, W]$$</span>，其中 <span class=\"formula\">$$T$$</span> 是帧数维度。第二段，多步去噪采样：对整段潜变量执行 <span class=\"formula\">$$N$$</span> 步流匹配或扩散采样，每一步都要跑一遍时空注意力（spatial attention 与 temporal attention 交替或联合），并且每一步的中间激活都要保留到下一步。第三段，VAE 解码：采样结束后，把整段潜变量一次性送进 VAE 解码器，还原成像素帧，再编码成视频容器返回。</p>\n<p>这套形状在图像生成上是合理的，因为图像只有两个空间维度、序列短、激活小。搬到视频上，三个维度同时膨胀：帧数 <span class=\"formula\">$$T$$</span> 让序列长度成倍增长，时空注意力中的 temporal attention 需要跨帧聚合，注意力矩阵的规模随 <span class=\"formula\">$$T$$</span> 平方级增长；多步采样意味着同一份潜变量要被反复读写 <span class=\"formula\">$$N$$</span> 次，每一步都是一次完整的显存往返；VAE 解码器本身参数量不小，且解码时的特征图分辨率高，峰值激活往往比采样阶段还猛。工程上最直接的后果是：<em>峰值显存由“整段”决定，而不是由“当前正在算的那一块”决定</em>。这就是旧方案的结构性缺陷——它没有把“时间”当作可以流式推进的维度，而是当作一个必须整体驻留的批维度。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-3\">三 · 痛点一：峰值显存的加法结构，把可部署档位锁死</h3>\n<p>把旧方案的显存占用写成式子，问题一目了然。整段处理时，峰值显存近似为所有时间块的激活与 KV 占用之和，再加上一次性 VAE 解码的开销：</p>\n<div class=\"formula\">$$\\mathrm{Mem}_{\\mathrm{peak}}^{\\text{old}} \\approx \\sum_{b=1}^{B}\\big(\\mathrm{Act}_{b}+\\mathrm{KV}_{b}\\big)+\\mathrm{VAE}_{\\mathrm{dec}}^{\\text{full}}$$</div>\n<p>注意求和号：旧方案里 <span class=\"formula\">$$B$$</span> 个时间块的激活是同时驻留的，因为它们属于同一个整段潜变量、同一次前向。这意味着显存峰值随视频长度线性增长，而 VAE 解码项又是一次性整段解码带来的额外尖峰。工程上的直接后果是容量规划被“最长视频”绑架：为了支持某个帧数上限，必须按最坏情况的峰值显存选卡、选机柜档位，短请求无法把省下来的显存还给系统。在 B200/GB200 这类显存容量固定的档位上，这等于把“能支持多长的视频”写死成一个硬件常数，而不是一个可调度的策略变量。</p>\n<p>具体例子：一个服务如果按整段方案部署，为了覆盖长视频请求，单卡显存预算必须留出整段激活加整段 VAE 解码的峰值；当并发请求数上升，每个请求都要求同样的整段预算，调度器只能拒绝新请求或排队，吞吐被显存而非算力卡住。论文的流式方案把求和号变成“逐块推进、已完成块释放”，峰值显存退化为“当前块激活 + 跨块缓存 + 按块 VAE 解码”，这是后续部分要展开的机制，但旧方案的代价在这里已经清楚：<em>显存峰值是加法，不是流水</em>。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-4\">四 · 痛点二：带宽被多步采样反复征收，算力反而闲置</h3>\n<p>视频扩散的采样步数多，每一步都要把潜变量、注意力权重、中间特征在 HBM 与计算单元之间搬一遍。旧方案整段处理时，每一步的读写量正比于整段潜变量的规模，于是总带宽消耗近似为步数与整段规模之积。用伪代码表达旧方案的内层循环：</p>\n<ul>\n<li>for step in 1..N: 对整段潜变量 X 计算时空注意力，读写整段 X 与整段 KV；</li>\n<li>每一步的激活写回 HBM，下一步再读回，没有跨步的驻留复用；</li>\n<li>采样结束后，整段 X 一次性送入 VAE，解码器的高分辨率特征图再次制造带宽尖峰。</li>\n</ul>\n<p>这套循环在 Blackwell 上的问题是：tcgen05 与 TMEM 的设计意图是让矩阵乘的累加器与操作数尽量留在片上，减少 HBM 往返；而旧方案的整段读写模式恰好把数据反复推出片上存储，带宽成为瓶颈，MMA 单元的利用率被内存等待拖低。也就是说，旧方案不是“算不动”，而是“算力在等数据”。对在线服务而言，这直接转化为时延：每一步的带宽等待叠加成端到端延迟，而吞吐受限于 HBM 带宽而非 tensor core 数量。论文的跨块缓存复用正是针对这一点——把上一块保留的键值与中间特征留在可复用位置，避免重复前向，这是后续部分的主题；此处只需记住旧方案的带宽账单是按“整段 × 步数”计的。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-5\">五 · 痛点三：长视频分块与重叠的重复计算，以及批调度与流式输出的矛盾</h3>\n<p>在旧方案里，长视频并非完全不能做，工程上常见的妥协是“分块 + 重叠窗口”：把长视频切成若干时间块，相邻块之间保留一段重叠帧，以保证块边界的时序连续性。这个妥协引入了两个旧方案无法回避的代价。其一是重复计算：重叠窗口内的帧会被相邻两块各算一遍，重叠越大、连续性越好，重复的时空注意力前向就越多，算力与带宽被成比例浪费。其二是块间等待：块是串行推进的，前一块的采样与解码没完成，后一块无法开始，尾延迟由“最慢的一块”决定，而不是由平均块决定。写成时延的近似：</p>\n<div class=\"formula\">$$T_{\\text{e2e}} \\approx \\sum_{b=1}^{B}\\big(T_{\\text{sample},b}+T_{\\text{decode},b}\\big)+T_{\\text{wait}}$$</div>\n<p>其中 <span class=\"formula\">$$T_{\\text{wait}}$$</span> 是块间同步与资源等待，重叠窗口让 <span class=\"formula\">$$T_{\\text{sample},b}$$</span> 里包含重复计算。更麻烦的是批调度：在线服务希望把多个请求拼成批以提高吞吐，但视频请求的块推进节奏不一致，流式输出又要求按块尽快吐出帧。旧方案要么整段批处理（吞吐好看，但首帧延迟与显存峰值难看），要么逐请求串行（时延可控，但吞吐塌陷）。这两者在 SLO 上不可兼得，而论文的调度器按块粒度推进批、依据显存水位调整批大小与重叠窗口，正是要把这个矛盾变成可调的权衡——这是后续部分的内容，但旧方案在这里的困境是实打实的：<em>批量与流式输出在整段处理范式下无法同时满足</em>。</p>\n<p>具体例子：一个并发升高的时刻，调度器若坚持整段批处理，显存水位迅速逼近上限，只能缩小批或拒绝请求，吞吐掉下来；若改为逐请求流式，单请求的块间等待又让尾延迟抖动，SLO 达标率下降。旧方案没有“按块调批”的中间地带，因为它的调度单位是整段请求，而不是时间块。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-6\">六 · 为什么非改不可：Blackwell 档位把旧方案的余量吃干净了</h3>\n<p>把上述三条代价放到 Blackwell 的部署语境里，结论是旧方案的余量不足以支撑长视频在线服务。第一，显存档位固定：B200/B300、GB200/GB300 NVL72 的每卡显存是一个确定的预算，整段方案的峰值显存随视频长度线性上涨，容量规划只能按最坏情况留余量，短请求无法回收这部分预算。第二，带宽是稀缺资源：多步采样反复读写整段潜变量，让 HBM 带宽成为端到端时延的主项，而 tcgen05/TMEM 的片上复用优势被整段读写模式抵消。第三，SLO 与吞吐的冲突在整段范式下无解：批调度单位太粗，流式输出单位太细，中间缺少“块”这一层调度粒度。第四，精度与显存策略受限：旧方案下低精度算子与 KV 缓存的收益被整段激活的峰值掩盖，量化省下来的显存很快被整段 VAE 解码的尖峰吃掉。</p>\n<p>因此这篇论文的动机不是“再快一点”，而是换掉调度单位：把推理组织成按时间块推进的流式管线，让峰值显存由块级激活与缓存占用决定，让 VAE 解码按块执行并流式输出，让调度器以块为粒度、以显存水位为信号调整批大小与重叠窗口。旧方案的三段式整段处理，在图像时代是合理的默认值，在长视频与有限显存档位的组合下变成了必须被替换的结构。后续部分将逐层拆开这个流式管线的分块调度器、时空注意力算子、跨块缓存管理与 VAE 解码模块，本部分的任务到此为止：把旧方案的账单算清楚，把“非改不可”的理由落在显存加法、带宽乘法与调度粒度这三个具体机制上。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-7\">七 · 在线短视频生成服务的显存墙：块间重叠的重复计算与批调度抖动</h3>\n<p>设想一个面向创作者的在线视频生成服务：请求进来时给出若干秒的潜变量序列，SLO 以首帧可见时间和整段完成时间衡量，同时同一张卡上还要混跑多个并发请求。在流式分块方案之前，这类负载的主流做法是整段一次性前向：把整条潜变量序列铺满显存，跑完所有采样步再统一送 VAE 解码。代价直接落在显存峰值上——时空注意力的激活与多步采样中的键值缓存随帧数线性甚至超线性增长，峰值显存近似为 <span class=\"formula\">$$\\mathrm{Mem}_{\\mathrm{peak}} \\approx \\sum_{b=1}^{B}\\big(\\mathrm{Act}_{b}+\\mathrm{KV}_{b}\\big)+\\mathrm{VAE}_{\\mathrm{dec}}$$</span> 其中 B 为时间块数。整段前向意味着 B 的求和项同时驻留，B 越大越容易顶到硬件档位上限；一旦越界，只能降并发或降分辨率，吞吐与 SLO 一起塌。</p>\n<p>分块流式把求和从“同时驻留”改成“逐块推进并释放”，峰值由单块激活加跨块缓存决定，这是它能压显存的机制根源。但边界也在这里：块间重叠窗口是为保持输出连续性而付的重复计算税。设块大小为 L、重叠为 O，则有效计算量放大约为 <span class=\"formula\">$$\\frac{L+O}{L}$$</span> 的重叠部分在相邻块被重复执行时空注意力。长视频下 B 增大，重复前向的绝对量随之累积，采样时延的下降会被这部分抵消；重叠越大越平滑，但显存与算力开销同时上升，调度器只能在时延与显存之间做显式权衡，而不是免费获得加速。</p>\n<p>第二个失效条件是批调度。流式输出按块解码并释放缓存，意味着每个请求的显存水位是随时间波动的锯齿形，而非整段前向那种一次性阶跃。并发升高时，若仍按请求级批大小推进，多个请求的块级峰值可能在同一时刻叠加，触发调度器缩小批大小或增大重叠来换稳定时延——后者恰恰又加重重复计算。于是高并发下出现“缩批→单请求时延变长→块间等待拉长→SLO 抖动”的反馈环，材料未给出阈值与监控指标，工程上只能靠峰值显存与块间等待时间两个观测量做回退判断。</p>\n<p>第三个边界是精度与算子支持。精度与显存策略围绕算子数值格式与 KV 缓存占用展开，收益依赖 Blackwell 档位上的算子支持；跨档位迁移时，同一分块大小与重叠窗口的显存账要重新验证，缓存复用带来的带宽节省也可能因数值格式不同而打折。换言之，这套方案把问题从“整段前向的显存墙”转成“块级调度与重叠参数的调参面”，可部署性提升，但失效模式从单点越界变成了并发下的时延抖动与重复计算累积，需要按块粒度做容量规划而非按请求粒度。</p>\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-8\">八 · 请求形态：块数、重叠与并发三轴</h3>\n<p>流式推理的请求不是“一段视频”这个整体，而是被调度器切成的时间块序列。因此负载形态的第一层刻画不是请求数，而是每个请求展开后的块数与重叠窗口：块数 <em>N<sub>b</sub></em> 由潜变量时间长度与块大小决定，重叠窗口 <em>O</em> 决定相邻块之间重复计算的比例。有效计算量近似为</p>\n<div class=\"formula\">$$C_{\\text{eff}} \\approx N_b \\cdot \\big(1 + \\tfrac{O}{L_b - O}\\big) \\cdot C_{\\text{blk}}$$</div>\n<p>其中 <em>L<sub>b</sub></em> 为块长，<em>C<sub>blk</sub></em> 为单块单步的时空注意力与流匹配计算量。这个式子说明：重叠不是免费的连续性保险，它按 <em>O/(L<sub>b</sub>−O)</em> 的比例直接放大总算力。工程上必须把 <em>O</em> 当作与批大小同级的调度变量，而不是固定超参。第二层是并发请求数 <em>R</em>，它决定调度器同时维护多少条块流水线；第三层是每请求的块粒度批大小 <em>b</em>。三者共同决定显存水位，因为峰值显存按块累加：</p>\n<div class=\"formula\">$$\\mathrm{Mem}_{\\mathrm{peak}} \\approx \\sum_{b=1}^{B}\\big(\\mathrm{Act}_{b}+\\mathrm{KV}_{b}\\big)+\\mathrm{VAE}_{\\mathrm{dec}}$$</div>\n<p>注意求和上界 <em>B</em> 是同时在显存中驻留的块数，而非请求总块数——这正是流式方案能压峰值的原因，也是负载形态直接塑造方案的地方：<em>R</em> 与 <em>b</em> 上升时 <em>B</em> 随之上升，调度器必须主动收缩。一个具体例子：8 秒、24fps 的潜变量序列在固定块大小下展开为十余个块，若重叠取块长的四分之一，有效计算量上升约三成；当并发从 1 提到 4，若不同步缩小 <em>b</em>，驻留块数翻倍，峰值显存按上式线性抬升，直接越过可部署档位。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-9\">九 · 输入长度分布与长尾</h3>\n<p>视频请求的长度分布是重尾的：大量短片段与少量长视频共存，而长视频的块数按长度线性增长，其显存与块间等待时间也线性增长。流式方案对短请求友好——块数少、驻留块少、VAE 解码次数少；对长尾请求则暴露两个代价。其一是块间等待：每块必须等上一块的跨块键值与中间特征就绪才能进入注意力，形成串行依赖链，端到端时延近似为</p>\n<div class=\"formula\">$$T_{\\text{e2e}} \\approx N_b \\cdot \\big(t_{\\text{attn}} + t_{\\text{cache}} + t_{\\text{dec}}\\big) + T_{\\text{tail}}$$</div>\n<p>其中 <em>t<sub>cache</sub></em> 是跨块缓存读写开销，<em>T<sub>tail</sub></em> 是最后一块解码与输出排空的时间。长尾请求的 <em>N<sub>b</sub></em> 大，串行链被拉长，SLO 压力集中在尾延迟而非均值。其二是重复计算随块数放大：重叠窗口在每个块边界都触发一次重复前向，长视频的累计浪费远高于短视频。测量口径上，必须按长度分桶统计，而不是只报全局均值——至少给出块数分位（p50/p90/p99 的 <em>N<sub>b</sub></em>）、对应桶的峰值显存与块间等待时间，否则长尾的代价会被短请求稀释掉。工程判断是：调度器应对长尾请求单独设档，缩小批大小或增大重叠以换取稳定时延，代价是吞吐下降，这一取舍必须显式记录在容量规划里。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-10\">十 · 批大小与 SLO 的耦合</h3>\n<p>块粒度批处理是流式方案兼顾吞吐与 SLO 的唯一杠杆，但它与 SLO 是双向耦合的。批大小 <em>b</em> 上升提高单块算子的利用率与吞吐，却按峰值显存公式抬升驻留占用；当显存水位逼近档位上限，调度器缩小 <em>b</em>，单块时延下降但总吞吐下降，SLO 从“吞吐达标”切换为“时延达标”。可核查的口径是把 SLO 拆成两个可测量：块间等待时间（反映串行链健康度）与峰值显存水位（反映是否触发收缩）。前者用每块进入与退出的时间戳差统计，后者用分配器的高水位采样。一个具体机制：调度器在每块开始前读取水位，若超过阈值则把 <em>b</em> 减半并增大重叠，保证块间等待不因显存换页而劣化；这一动作本身有代价——批减半使算子利用率下降，吞吐按近似线性回落，因此收缩策略必须带滞回，避免在水位边界反复抖动。论文材料未给出具体阈值与监控指标，因此部署时应把这两个量作为一等指标接入监控，而不是事后补测。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-11\">十一 · 负载如何反向限制方案</h3>\n<p>方案不是单向适配负载，它反过来给负载划出可行域。流式管线的块大小与重叠窗口一旦固定，就限定了单请求的最短可服务长度与最长可服务长度：块太小则重叠比例 <em>O/(L<sub>b</sub>−O)</em> 爆炸，重复计算吞掉收益；块太大则驻留激活抬高峰值显存，抵消流式的压缩效果。并发上限同样被方案锁定：<em>R</em> 受限于同时驻留块数 <em>B</em> 与缓存容量，而 <em>B</em> 又由块大小与批大小决定，形成一条“块大小—批大小—并发”的三角约束。精度策略进一步收紧可行域：算子数值格式与 KV 缓存占用决定每块的字节开销，收益受硬件档位与算子支持限制，跨档位可移植性未验证，意味着在一个档位上标定的负载上限不能直接搬到另一档位。工程含义是：容量规划必须以“块大小 × 批大小 × 并发”的三元组为单位做标定表，而不是以请求数为单位；任何一项变更都要重测峰值显存与块间等待，否则 SLO 承诺没有依据。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-12\">十二 · 可核查的测量口径</h3>\n<p>为避免结论停留在定性层面，测量应固定以下口径，且全部可按块粒度采集。</p>\n<ul>\n<li>块级时间戳：每块进入注意力、缓存读写完成、VAE 解码完成三个时刻，导出块间等待时间分布，按块数分桶。</li>\n<li>峰值显存：以分配器高水位为准，记录每请求的驻留块数与 <em>B</em> 的实际取值，验证峰值显存公式的求和上界。</li>\n<li>有效计算量：用 <em>N<sub>b</sub></em> 与重叠比例算出 <em>C<sub>eff</sub></em>，与实际算子计数对照，量化重叠带来的重复计算占比。</li>\n<li>吞吐与 SLO 双指标：分别报告块/秒与块间等待的 p99，避免用均值掩盖长尾。</li>\n<li>收缩事件日志：记录每次批大小或重叠调整的水位触发点与滞回区间，用于评估调度抖动的代价。</li>\n</ul>\n<p>这些口径的共同点是都以块为原子单位，与流式管线的推进方式对齐；以请求为单位统计会把串行链与重复计算混在一起，无法定位代价来源。论文材料未给出数据集、基线与具体数字，因此上述口径应作为部署侧的标定框架，而非对论文结论的复现。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-13\">十三 · 失败模式的负载侧根源</h3>\n<p>材料列出的失败模式——重叠导致重复计算被低估、流式输出对批调度敏感、精度策略依赖算子支持——都能在负载形态里找到根源。重复计算被低估，是因为容量规划常按请求数而非块数建模，长尾请求的 <em>N<sub>b</sub></em> 被均值掩盖；批调度敏感，是因为并发升高时 <em>R</em> 与 <em>b</em> 同时挤压 <em>B</em>，收缩动作本身引入抖动，而 SLO 稳定性缺乏数字支撑；精度策略的跨档位问题，则是因为每块字节开销随数值格式变化，负载上限随之漂移。工程判断落在具体机制上：把块间等待与峰值显存水位作为调度器的输入信号，用带滞回的批大小与重叠调整维持 SLO，并把三元组标定表作为容量承诺的唯一依据——负载塑造方案，方案限定负载，闭环就在这两个信号上。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-14\">十四 · 块粒度负载：流式管线的容量边界与失效条件</h3>\n<p>流式推理把“请求”从整段视频重定义为<strong>块序列</strong>，负载形态因此不再是单一的输入长度分布，而是三维分布：块数 <em>N</em><sub>b</sub>（由视频时长与块大小决定）、每块并发请求数、以及重叠窗口 <em>o</em>。调度器按块推进，批大小以块为粒度组织，这带来一个直接后果——<strong>吞吐与 SLO 的计量单位必须换成“块/秒”与“块间等待时间”</strong>，而不是整段视频的端到端时延。可核查的口径是：在固定采样步数下，记录每块从入队到 VAE 解码完成的时间戳，取相邻块时间戳差值的分布，其 p99 即块间等待的长尾；同时采样 <code>nvidia-smi</code> 或 DCGM 的显存水位，与调度器的缩批/增重叠动作对齐时间轴，才能判断一次 SLO 抖动是负载造成还是调度策略自身振荡造成。峰值显存按块级累加估算：</p>\n<div class=\"formula\">$$\\mathrm{Mem}_{\\mathrm{peak}} \\approx \\sum_{b=1}^{B}\\big(\\mathrm{Act}_{b}+\\mathrm{KV}_{b}\\big)+\\mathrm{VAE}_{\\mathrm{dec}}$$</div>\n<p>该式说明容量边界由三项共同决定：块级激活、跨块保留的 KV 与中间特征、以及 VAE 解码器的常驻占用。工程上真正卡住并发的是第二项——缓存复用要求上一块的键值与特征在下一块计算期间仍然驻留，于是<strong>缓存占用随并发线性增长而不会随块完成立即回落</strong>，这与常规连续批处理“请求结束即释放”的直觉相反。失效条件由此明确：当并发请求数上升使缓存项逼近显存水位阈值时，调度器只能缩小批大小或增大重叠窗口；前者降低吞吐，后者按 <em>o</em>/(块大小) 的比例引入重复时空注意力计算，二者都在恶化时延。换言之，流式方案的容量上限不是由单块算力决定，而是由“缓存驻留 × 并发”决定的，长视频（块数多）只是把这个上限更早地暴露出来。</p>\n<p>重叠窗口是负载与方案互相塑造的典型接口。重叠增大可提升块间输出连续性、掩盖块边界处的注意力上下文缺失，代价是重复前向；重叠减小则反之。可核查的权衡口径是<strong>单位输出帧的有效计算量</strong>：设块长为 <em>L</em>、重叠为 <em>o</em>，则每前进 <em>L−o</em> 帧需计算 <em>L</em> 帧的注意力，冗余率为 <em>o</em>/(<em>L−o</em>)。当并发升高触发调度器增大重叠以换取“稳定时延”时，冗余率同步上升，带宽压力随之上升——在 Blackwell 上这意味着 TMEM 与 HBM 之间的搬运次数增加，而时空注意力的算术强度本就不高，冗余计算很容易把管线推入带宽受限区。因此“增大重叠换稳定”只在算力富余、带宽未饱和时成立；一旦进入带宽受限区，该动作反而延长块间等待，形成正反馈式的 SLO 劣化。这是材料中“流式输出对批调度敏感”的具体机制解释，也是跨档位迁移必须重新验证的原因：不同 SM 档位的算子支持与带宽配比不同，同一重叠策略的冗余代价并不等价。</p>\n<p>长尾的来源需要分开计量，否则会把调度问题误判为模型问题。第一类长尾是<strong>块数长尾</strong>：少数超长视频请求占据缓存驻留时间最久，拖住整体水位；第二类长尾是<strong>块间等待长尾</strong>：由缩批动作与重叠调整引起，表现为周期性尖峰而非随机抖动；第三类是第一块与最后一块的“边缘块”——首块无缓存可复用、末块解码后需等待流式输出收尾，二者时延结构与其他块不同，混入统计会污染 p99。可操作的口径是按块序号分层统计等待时间，并对缓存驻留时长单独打点。回退策略上，材料给出的动作是缩小分块或降低精度，但两者代价不同：缩小分块降低单块激活与缓存粒度、提升调度灵活性，却增加块数与块间开销；降低精度压缩 KV 与激活占用，但收益受算子数值格式支持限制，且需重新验证输出质量。工程判断应落在<strong>把回退触发条件绑定到“缓存驻留 × 并发”这一乘积而非单一显存水位</strong>，并在灰度中同时观测冗余率与块间等待 p99，避免用吞吐指标掩盖 SLO 长尾。</p>\n<table class=\"mini\"><thead><tr><th>负载维度</th><th>塑造方案的机制</th><th>方案反向限制</th><th>可核查口径</th></tr></thead><tbody><tr><td>块数 N<sub>b</sub></td><td>决定缓存驻留时长与总块数</td><td>长视频提前触达水位阈值</td><td>按块序号分层统计等待时间</td></tr><tr><td>并发请求数</td><td>缓存占用线性增长</td><td>缩批导致吞吐下降</td><td>缓存驻留 × 并发 与水位对齐</td></tr><tr><td>重叠窗口 o</td><td>换取输出连续性</td><td>冗余率 o/(L−o) 推高带宽</td><td>单位输出帧有效计算量</td></tr></tbody></table>\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-15\">十五 · 从块级激活到算子选型：精度为什么是流式推理的第一性约束</h3>\n<p>流式推理把显存峰值写成块级激活与缓存的加和，这个式子决定了精度策略的落点不在“整模型量化”而在“逐算子选型”。<div class=\"formula\">$$\\mathrm{Mem}_{\\mathrm{peak}} \\approx \\sum_{b=1}^{B}\\big(\\mathrm{Act}_{b}+\\mathrm{KV}_{b}\\big)+\\mathrm{VAE}_{\\mathrm{dec}}$$</div>逐项看：$B$ 是同时驻留的块数，由调度器的重叠窗口与批大小共同决定；$\\mathrm{Act}_{b}$ 是第 $b$ 块在时空注意力与流匹配采样步中产生的激活，其字节数正比于块内 token 数乘以每 token 的位宽；$\\mathrm{KV}_{b}$ 是跨块复用的键值缓存，随块数与头维度线性增长；$\\mathrm{VAE}_{\\mathrm{dec}}$ 是按块解码时的解码器工作集。三项中前两项都直接乘上数值格式的位宽因子——把激活从 BF16 降到 FP8，$\\mathrm{Act}_{b}$ 减半；把 KV 缓存降到 FP8，$\\mathrm{KV}_{b}$ 减半。这意味着精度不是“锦上添花的加速手段”，而是流式管线能否在给定显存档位下把重叠窗口开大的前置条件：重叠窗口越大，跨块复用越充分、重复时空注意力前向越少，但驻留块数 $B$ 上升。精度压缩换来的位宽余量，正好用来买更大的重叠。</p>\n<p>代价侧要看清：降精度省的是显存容量与带宽，不是免费。视频扩散的采样步对数值误差敏感，尤其是流匹配目标下速度场的累积误差会在多步积分中放大；VAE 解码对激活的动态范围更敏感，末层重建误差直接体现在帧上。因此算子选型必须按“误差放大路径”排序：跨块 KV 缓存复用跨越多个采样步，误差累积最长，是精度最敏感的部位；块内注意力的 QK^T 与 PV 是短路径，可用低精度；VAE 解码是输出路径，需保留较高精度或做选择性回退。一个具体例子：在 GB200 NVL72 的单卡档位上部署长视频分块采样，若 KV 缓存保持 BF16 而块内注意力走 FP8，$\\mathrm{KV}_{b}$ 成为 $\\mathrm{Mem}_{\\mathrm{peak}}$ 的主导项，重叠窗口被迫收窄，块间等待上升；反之把 KV 缓存压到 FP8、块内注意力保持 BF16，容量让给重叠窗口，重复计算下降，端到端时延反而更优。这就是“精度预算应按缓存路径而非算力路径分配”的工程判断。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-16\">十六 · 核心 kernel 的分解：时空注意力、流匹配步与 VAE 解码的精度分工</h3>\n<p>流式管线的三个核心 kernel 各有不同的数值结构，精度策略不能一刀切。时空注意力在块内是标准的多头注意力，QK^T 的累加长度等于块内 token 数，PV 的累加长度等于头维度；跨块复用则把历史块的 K、V 拼接进来，累加长度随重叠窗口增长。流匹配采样步本质是逐元素的向量场评估与积分更新，算子以逐元素乘加与归约为主，对累加精度的要求集中在归约树上。VAE 解码是卷积/反卷积堆叠，激活动态范围随层深变化，末层输出直接决定像素。</p>\n<p>对应的精度分工可以写成伪代码思路：</p>\n<ul>\n<li>块内注意力：Q、K、V 用 FP8（E4M3）存储与相乘，QK^T 与 PV 的累加在 FP32 完成，softmax 的指数与归一化在 FP32 做，避免 FP8 下溢导致的注意力权重塌缩。</li>\n<li>跨块 KV 缓存：缓存本体用 FP8 存储以压缩 $\\mathrm{KV}_{b}$，读取后立即提升到 BF16 参与 PV 累加，累加器保持 FP32；缓存的量化尺度按块独立标定，避免跨块动态范围漂移。</li>\n<li>流匹配步：向量场评估的逐元素运算用 BF16 或 FP8，积分更新的状态变量（潜变量）保持 BF16 或 FP32，防止多步累积的舍入误差。</li>\n<li>VAE 解码：主体用 BF16，末两层与输出投影保留 FP16 或 BF16 高精度路径，必要时对末层做逐通道尺度校正。</li>\n</ul>\n<p>系统代价上，FP8 路径的收益主要在带宽而非算力：视频扩散推理的瓶颈是激活与缓存的读写，第五代 Tensor Core 的 FP8 吞吐远高于访存带宽，因此把算子压到 FP8 的实际收益取决于该算子是否受带宽约束。时空注意力的 PV 与 KV 读取是带宽密集的，FP8 收益直接；流匹配步的逐元素运算受算力与寄存器约束，FP8 收益有限但寄存器压力下降可换来更大 tile。一个具体例子：块内注意力在 FP8 下把 K/V 的读取字节减半，重叠窗口从固定块大小推进到更大窗口时，$\\mathrm{KV}_{b}$ 的驻留成本被抵消，调度器得以在显存水位不变的前提下增大重叠，减少块间重复前向——这正是精度与调度耦合的地方。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-17\">十七 · 累加精度与误差传播：FP32 累加器为什么不能省</h3>\n<p>低精度存储不等于低精度计算。矩阵乘的误差由两部分构成：输入量化的表示误差，以及累加过程中的舍入误差。后者在长归约上会累积成系统性偏差，尤其在注意力 softmax 前的 logits 上，偏差会改变权重分布而非仅仅引入噪声。因此 Blackwell 上的 tcgen05 MMA 路径把累加器放在 TMEM 中并以 FP32 精度累加，这不是可选优化而是数值正确性的底线。</p>\n<div class=\"formula\">$$\\epsilon_{\\mathrm{acc}} \\approx \\sqrt{N}\\cdot\\epsilon_{m}\\cdot\\|a\\|\\|b\\|,\\qquad \\epsilon_{q}=\\frac{\\Delta}{2}=\\frac{2^{-(e-b)}}{2}$$</div>\n<p>第一式给出归约长度 $N$ 下累加误差的量级估计：$\\epsilon_{m}$ 是单次乘加的舍入误差，$\\|a\\|\\|b\\|$ 是参与归约的向量范数积，误差随 $\\sqrt{N}$ 增长——这意味着跨块 KV 复用把 $N$ 从块内长度扩大到块内加历史长度时，累加误差的增长是可预期的，但若累加器降到 FP16，$\\epsilon_{m}$ 跃升数个量级，$\\sqrt{N}$ 的放大就不可接受。第二式是量化步长与指数位宽 $e$、尾数位宽 $b$ 的关系：FP8 E4M3 的尾数只有 3 位，$\\Delta$ 远大于 BF16 的 7 位尾数，表示误差在动态范围边缘急剧恶化。</p>\n<p>工程含义有三条。其一，累加器精度必须与归约长度匹配：块内注意力可用 FP32 累加配 FP8 输入，跨块复用的 PV 归约长度更长，累加器更不能降。其二，softmax 的数值稳定需要 FP32 的指数与归一化，FP8 下溢会让远距离块的注意力权重被清零，表现为跨块连续性断裂——这是流式输出最怕的失败模式。其三，流匹配积分的状态变量误差是跨步累积的，单步误差小但步数多，状态保持 BF16 以上是必要的。代价侧：FP32 累加器占用 TMEM 容量，TMEM 是 Blackwell 上有限的片上资源，累加器位宽翻倍会压缩可并行的 MMA tile 数，进而影响吞吐。因此在 TMEM 预算内做“哪些归约用 FP32、哪些用 BF16”的分配，是 kernel 设计的核心权衡。一个具体例子：跨块注意力的 PV 归约若用 BF16 累加器，长重叠窗口下注意力输出出现块边界处的亮度跳变，VAE 解码后表现为帧间闪烁；切回 FP32 累加后跳变消失，代价是 TMEM 占用上升、单块 MMA 吞吐下降，调度器需相应缩小批大小以维持显存水位。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-18\">十八 · Blackwell 特性如何改变精度决策：tcgen05、TMEM 与 2-SM MMA</h3>\n<p>第五代 Tensor Core 的 tcgen05 指令族把矩阵乘的累加器从寄存器堆搬到 TMEM，这是一次资源位置的迁移，直接改写精度预算的分配方式。传统路径上累加器占寄存器，FP32 累加会挤占寄存器文件、压低 occupancy；tcgen05 把累加器放进 TMEM 后，寄存器压力释放，FP32 累加的代价从“占用寄存器”变成“占用 TMEM 容量”。TMEM 容量有限但访问模式规整，适合长归约的累加器驻留——这正好匹配跨块 KV 复用的长归约需求。</p>\n<p>2-SM MMA 是另一项结构性变化：两个 SM 协同执行一次 MMA，共享操作数并合并累加。对精度而言，2-SM 模式让更大的 tile 在相同累加器位宽下可行，因为累加器容量由两个 SM 的 TMEM 共同承担；对系统而言，它降低了每 SM 的权重与激活读取次数，带宽压力下降。视频扩散的时空注意力在块内是规整的方阵乘，2-SM MMA 能把块内注意力的 tile 做大，减少边界处的重复读取；跨块复用的拼接则需要注意 K/V 拼接后的对齐，2-SM 模式下拼接边界若不对齐会退化为标量路径，带宽收益消失。</p>\n<p>代价与判断：tcgen05 与 2-SM MMA 的收益依赖 tile 形状与对齐，块大小与重叠窗口的选择不再是纯调度问题，而是与 kernel 的 tile 约束耦合。若块大小选得使 tile 无法对齐到 2-SM 的合并粒度，MMA 效率下降，精度上省下的带宽被低效计算吃掉。一个具体例子：把块内 token 数取为 2-SM MMA 合并 tile 的整数倍，跨块拼接时历史 K/V 按 tile 边界对齐存放，PV 归约在 TMEM 中以 FP32 累加，此时重叠窗口增大带来的长归约误差被 FP32 累加吸收，而带宽因 2-SM 共享读取而下降；反之若块大小随意选取，拼接边界错位导致部分 MMA 走非合并路径，吞吐与精度收益同时落空。这解释了为什么流式推理的块大小不能只按显存水位定，还要按目标硬件的 MMA tile 约束定。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-19\">十九 · NVFP4 的边界：块级缩放与流式管线的适配条件</h3>\n<p>NVFP4 在 Blackwell 上把权重与激活压到 4 位，配合块级缩放因子恢复动态范围。其数值结构是每若干元素共享一个缩放因子，元素本身是 E2M1 的 4 位浮点。对视频扩散推理，NVFP4 的吸引力在于把 $\\mathrm{Act}_{b}$ 与 $\\mathrm{KV}_{b}$ 再压一半，从而在相同显存档位下把重叠窗口推到更大；但边界同样清晰。</p>\n<div class=\"formula\">$$x_{q}=\\mathrm{round}\\!\\left(\\frac{x}{s}\\right),\\qquad s=\\frac{\\max(|x|)}{2^{e_{\\max}}}\\ \\text{(per-block)}$$</div>\n<p>缩放因子 $s$ 按块取最大绝对值标定，块越小动态范围匹配越好但元数据开销越大；块越大元数据省但块内动态范围被拉伸，小值被量化到零。对流式管线，跨块 KV 缓存的块级缩放必须按块独立标定，否则历史块与新块的动态范围差异会让复用缓存的低位信息丢失。代价侧：NVFP4 的矩阵乘需要反量化路径，反量化的算力开销与缩放因子的读取带宽会部分抵消位宽收益；在带宽密集的 PV 归约上收益明显，在算力密集的逐元素流匹配步上收益有限。</p>\n<p>适配条件可以归纳为三条判断：其一，NVFP4 适合权重与块内激活，不适合跨块 KV 缓存的长归约输入，因为长归约对表示误差的放大更敏感；其二，NVFP4 的缩放因子标定必须与块调度对齐，块大小变化时缩放因子需重标定，否则跨块复用的一致性被破坏；其三，NVFP4 的收益要在显存水位约束下评估——若显存已不是瓶颈而带宽是，NVFP4 的反量化开销可能使端到端时延不降反升。一个具体例子：在长视频分块采样中把块内注意力输入压到 NVFP4、KV 缓存保持 FP8，$\\mathrm{Act}_{b}$ 下降使重叠窗口得以扩大，块间重复前向减少；但若把 KV 缓存也压到 NVFP4，跨块 PV 归约的表示误差在长窗口下累积，输出帧出现块边界色偏，VAE 解码无法掩盖。这说明 NVFP4 的落点是“短路径激活”，而非“长路径缓存”。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-20\">二十 · 精度回退与调度器的联动：把数值格式当作可调档位</h3>\n<p>流式推理的调度器依据显存水位调整批大小与重叠窗口，精度格式应当作为同一控制回路里的第三个旋钮。材料明确指出精度与显存策略的收益受硬件档位与算子支持限制、跨档位可移植性未验证，因此工程上不能把某一精度配置写死，而要把“格式档位”与“块大小、重叠、批大小”一起纳入回退策略。</p>\n<ul>\n<li>水位升高时的回退顺序：先缩批大小，再缩重叠窗口，最后降精度格式。降精度是最后手段，因为它改变数值语义、影响跨块缓存的一致性，回退后需要重标定缩放因子并可能触发缓存失效。</li>\n<li>精度回退的粒度按算子而非整模型：跨块 KV 缓存从 FP8 回退到 BF16 只影响缓存路径，块内注意力保持 FP8 不受影响；这种局部回退避免整条管线重编译。</li>\n<li>监控指标应包含数值一致性而非仅显存与等待时间：块边界处的输出差异、注意力权重的分布漂移是精度回退的早期信号，材料未给出具体阈值，工程上需自行标定。</li>\n</ul>\n<p>系统代价在于回退的切换成本：精度格式切换可能触发 kernel 重选与缓存重标定，切换期间的块间等待上升，SLO 出现瞬时抖动。因此回退策略需要滞回区间，避免在水位边界反复切换。一个具体例子：并发升高使显存水位逼近上限，调度器先缩批，块间等待上升但仍满足 SLO；水位继续升高时缩重叠窗口，跨块复用减少、重复时空注意力前向增加，时延上升；若仍不足则把 KV 缓存从 FP8 回退到 BF16，缓存占用翻倍但数值一致性恢复，代价是重叠窗口必须进一步收窄。这条回退链的每一级都在“显存—时延—数值一致性”三角上移动，精度格式是唯一改变数值语义的一级，因此必须放在最后并有明确的恢复条件。最终落在工程判断上：在 Blackwell 档位上，精度不是静态配置项，而是与分块调度共享控制回路的动态档位；把 tcgen05 的 TMEM 累加预算、2-SM MMA 的 tile 对齐、NVFP4 的块级缩放一起纳入块大小与重叠窗口的选取，才能让流式管线的显存峰值与采样时延同时受控。</p>\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-21\">二十一 · 显存账本的三个户头：权重、激活、KV</h3>\n<p>把视频扩散推理的显存拆成三本账，是判断“能不能塞进这一档卡”的唯一可靠起点。第一本是权重：DiT 主干加 VAE 解码器，参数在推理期是只读的，占用等于参数量乘每参数字节数；在 Blackwell 上权重常驻 HBM，NVFP4 与 FP8 的差别直接体现在这一项上，但权重是常数项，不随请求变化，因此它决定的是“能不能装下”，而不是“能跑多长”。第二本是激活：每个时间块的潜变量、注意力中间结果、FFN 展开张量，随块大小与批大小线性增长，是峰值显存的主要变量项。第三本是 KV：时空注意力保留的键值对，跨块复用时它是收益来源，不复用时它是纯开销。论文的峰值公式把这本账写得很直白：</p>\n<div class=\"formula\">$$\\mathrm{Mem}_{\\mathrm{peak}} \\approx \\sum_{b=1}^{B}\\big(\\mathrm{Act}_{b}+\\mathrm{KV}_{b}\\big)+\\mathrm{VAE}_{\\mathrm{dec}}$$</div>\n<p>注意求和号落在块上而不是落在层上，这暗示了论文的组织方式：块是调度与释放的基本单位。工程上要补一层：$\\mathrm{Act}_b$ 内部还要按层展开，单层峰值往往出现在时空注意力的打分矩阵上，而不是整块的平均占用。举例说，一个按时间块推进的长视频请求，若块内帧数为 $T_b$、空间 token 数为 $S$、隐藏维为 $d$，则单块激活的量级约为 $T_b\\cdot S\\cdot d$ 乘每元素字节数，再乘注意力并发层数带来的瞬时放大；把 $T_b$ 减半，激活项近似减半，但块数翻倍、块间重叠带来的重复前向也随之增加。这就是账本的第一条张力。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-22\">二十二 · KV 的分页、压缩与复用：省的是带宽，不是容量</h3>\n<p>视频扩散的 KV 与语言模型不同：它不是自回归增长的，而是每个采样步都要对同一批潜变量重算或复用。论文的做法是跨块保留键值与中间特征，使相邻块在重叠窗口内不必重新做完整的时空注意力前向。这带来两个必须分开看的收益：容量上，复用意味着同一份 KV 被多个块引用，若引用计数管理得当，KV 池的峰值等于“活跃块数 × 单块 KV”，而不是“总块数 × 单块 KV”；带宽上，复用把一次 HBM 读取代替了一次完整的 QKV 投影加注意力计算，节省的是算力与访存往返，而不只是字节。</p>\n<p>分页在这里的作用不是解决碎片，而是解决“块完成顺序与释放顺序不一致”。流式管线里块的采样完成时间受重叠窗口与批调度影响，先完成的块其 KV 仍被后续块引用，不能立即归还；分页把 KV 切成固定大小的页，用页表而非连续缓冲区管理，引用计数归零才回收。压缩则要谨慎：KV 的低位量化会直接进入注意力打分，误差在多个采样步上累积，视频的时序一致性对此比单帧图像更敏感。工程判断是——KV 压缩的收益主要体现在带宽侧（同样容量下更多页可驻留、更少换出），容量侧的收益必须用输出质量来换，且论文材料未给出具体量化方案，跨档位可移植性未验证，因此不应把 KV 量化当作默认开关。</p>\n<p>代价要算清楚：假设单块 KV 为 $K$ 字节、活跃块数为 $A$、重叠窗口使平均引用数为 $r$，则 KV 池容量约为 $A\\cdot K$，而重复计算量为 $(r-1)\\cdot A$ 次块级前向。$r$ 增大压低重复计算却抬高活跃块数，这是一条单调相反的曲线，调度器的重叠参数就是在这一点上做取舍。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-23\">二十三 · 复用与卸载：把常数项挪出 HBM</h3>\n<p>复用有两个层次。块内复用是算子级的：时空注意力在同一块的不同采样步之间共享部分中间特征，论文的缓存管理保留跨块中间特征以避免重复前向，本质是把“每步重算”改成“跨步持有”。块间复用是调度级的：重叠窗口内的键值由前一块产出、后一块消费，消费完即释放。两层复用的共同代价是缓存生命周期变长，活跃集变大，于是峰值显存不降反升的风险始终存在——这正是调度器要盯显存水位的原因。</p>\n<p>卸载针对的是权重这本常数账。VAE 解码器在采样阶段完全空闲，把它从 HBM 挪到主机内存或 NVMe，只在按块解码时换入，可以把 $\\mathrm{VAE}_{\\mathrm{dec}}$ 从峰值公式里的大部分时间抹掉。代价是换入的 PCIe 往返延迟会直接落在块间等待时间上，而流式输出对块间等待极敏感：解码一块、输出一块、再解码下一块，任何一次换入抖动都会变成可见的卡顿。因此卸载的粒度应是“解码器整体”而非“逐层”，并且要与块调度错峰——在采样块 $b+1$ 计算期间预取解码器，使换入延迟被计算掩盖。这条策略的收益是容量，代价是带宽与调度复杂度，属于典型的用确定性换空间。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-24\">二十四 · 带宽瓶颈在哪：HBM3e 容量怎么算</h3>\n<p>Blackwell 档位的 HBM3e 容量决定了权重、KV 池与激活三者之和的上限。可复算的算法是：先按部署精度算出权重字节数 $W$，再从总容量 $C$ 中扣除运行时保留（框架、通信缓冲、碎片余量，工程上按比例预留），剩余部分在 KV 池与激活峰值之间分配。写成约束是：</p>\n<div class=\"formula\">$$W + A\\cdot K + \\max_b\\big(\\mathrm{Act}_b\\big) + \\mathrm{VAE}_{\\mathrm{dec}} \\le C\\cdot(1-\\rho)$$</div>\n<p>其中 $\\rho$ 是预留比例。给定 $W$ 与 $C$ 后，这条不等式给出的是“活跃块数上限”，而活跃块数又反过来约束批大小与重叠窗口——容量规划在这里闭环。带宽侧的瓶颈位置则不同：时空注意力的打分与 softmax 是访存密集型，KV 复用省下的是重复读取；VAE 解码是另一类，它按块流式执行，每次只处理一块的潜变量，访存模式相对规整，真正的压力来自与采样阶段争抢 HBM 带宽。当采样与解码在同一条流上串行时，二者不冲突；一旦用双流并行掩盖解码延迟，带宽竞争就会显形，表现为采样步时延的抖动而非平均吞吐下降。判断带宽瓶颈的方法不是看利用率数字，而是看“缩小批大小后单块时延是否同比下降”——若同比下降明显，瓶颈在容量与调度；若几乎不变，瓶颈在带宽。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-25\">二十五 · 一个可复算的显存预算</h3>\n<p>下面给出一个只依赖符号、可代入实际参数复算的预算表。设隐藏维 $d$、单块空间 token 数 $S$、块内帧数 $T_b$、层数 $L$、每元素字节数 $e_w$（权重）与 $e_a$（激活/KV）、活跃块数 $A$、批大小 $N_b$。</p>\n<table class=\"mini\"><thead><tr><th>账目</th><th>表达式</th><th>随什么增长</th><th>工程手段</th></tr></thead><tbody>\n<tr><td>权重</td><td>$W \\approx P\\cdot e_w$</td><td>参数量、精度格式</td><td>低精度、卸载 VAE</td></tr>\n<tr><td>单块激活</td><td>$\\mathrm{Act}_b \\approx c\\cdot N_b\\cdot T_b\\cdot S\\cdot d\\cdot e_a$</td><td>批、块长、分辨率</td><td>缩批、缩块、分页</td></tr>\n<tr><td>单块 KV</td><td>$K \\approx 2\\cdot L\\cdot T_b\\cdot S\\cdot d\\cdot e_a$</td><td>层数、块长、精度</td><td>复用、压缩、引用计数</td></tr>\n<tr><td>KV 池</td><td>$A\\cdot K$</td><td>活跃块数、重叠窗口</td><td>调重叠、及时释放</td></tr>\n<tr><td>VAE 解码</td><td>$\\mathrm{VAE}_{\\mathrm{dec}}$</td><td>解码器规模</td><td>按块流式、卸载换入</td></tr>\n</tbody></table>\n<p>复算步骤：代入 $d$、$S$、$T_b$、$L$ 得单块 KV 与激活；用容量不等式解出 $A$ 的上限；再由 $A$ 与重叠窗口 $r$ 的关系确定批大小 $N_b$。举例说，若把 $T_b$ 从较大值减半，单块激活与单块 KV 都近似减半，但块数翻倍使总前向次数上升，且重叠窗口不变时相对重复计算比例上升——峰值下降、时延上升，这正是论文消融围绕块大小与重叠窗口展开的原因。反过来，若显存水位升高而调度器选择“增大重叠”，那是用更多活跃块换更少重复计算，属于在容量充裕时压时延的手段；水位紧张时应缩批或缩块，而不是加重叠。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-26\">二十六 · 调度器与显存水位的耦合</h3>\n<p>论文的调度器按块粒度推进批，并依据显存水位调整批大小与重叠窗口。这条机制的工程含义是：显存不是被动约束，而是控制回路的输入信号。水位上升时缩小批，直接压低 $\\mathrm{Act}_b$ 与并发块数；水位继续上升则回退到更小分块或更低精度——材料明确把这两条列为异常回退路径，但未给出阈值与监控指标。可操作的监控量是峰值显存与块间等待时间，前者对应容量约束，后者对应 SLO；两者同时恶化说明重叠窗口设置与批大小不匹配，应优先缩批而非加重叠。</p>\n<p>需要点明的是，块级批调度与连续批处理的目标函数不同：连续批处理追求 token 级吞吐填满，块级调度追求块间等待时间可控。视频扩散的流式输出使后者更贴近用户感知，因此调度器在并发升高时缩批，本质是牺牲吞吐换 SLO 稳定性。这条判断在 Blackwell 档位上尤其成立：当权重与 KV 池已占据容量大头，激活的边际增长极快，缩批是唯一低成本的即时手段。至于精度与显存策略的收益，材料只说明其围绕算子数值格式与 KV 缓存占用展开、受硬件档位与算子支持限制，跨档位迁移需重新验证——这句话应被读作“不要把上一档的量化配置直接搬到下一档”，而不是一句免责声明。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-27\">二十七 · 流式账本的边界：重叠税、水位回退与跨档位可移植性</h3>\n<p>这套分块流式方案的显存收益并非无代价，它把峰值显存从“整段视频一次性驻留”改写为“块级激活 + 跨块缓存 + 解码器”的滚动账本，公式 <span class=\"formula\">$$\\mathrm{Mem}_{\\mathrm{peak}} \\approx \\sum_{b=1}^{B}\\big(\\mathrm{Act}_{b}+\\mathrm{KV}_{b}\\big)+\\mathrm{VAE}_{\\mathrm{dec}}$$</span> 中的求和项随块推进逐项释放，但重叠窗口使相邻块共享的键值与中间特征必须同时驻留，重叠比例 <span class=\"formula\">$$r_{\\mathrm{ov}}=W_{\\mathrm{ov}}/W_{\\mathrm{blk}}$$</span> 每提高一档，重复的时空注意力前向就按 <span class=\"formula\">$$r_{\\mathrm{ov}}/(1-r_{\\mathrm{ov}})$$</span> 的比例放大算力与带宽开销——这是“重叠税”，在长视频上尤其容易被低估：块数 B 增大时，重叠引入的冗余前向总量线性增长，而峰值显存只降不升，二者并不对称。</p>\n<p>失效条件集中在三处。其一是块间等待：流式输出要求第 b 块解码完成才能推进第 b+1 块，若单块时空注意力时延超过块间 SLO 预算，缩小批大小换来的显存余量反而拉长排队，吞吐与 SLO 同时受损。其二是水位回退的抖动：调度器按显存水位缩小批或增大重叠，但阈值与监控指标材料未给出，回退到更小分块或更低精度会改变算子数值格式，跨档位迁移需重新验证，缓存复用逻辑在精度切换点可能失效。其三是并发敏感性：批按块粒度组织，并发升高时批被压缩，跨块缓存的命中窗口变窄，复用收益随负载漂移，SLO 稳定性缺乏数字支撑。</p>\n<p>系统代价要按 Blackwell 档位复算：HBM3e 容量决定可驻留的块数与缓存深度，带宽决定每块键值读写与 VAE 解码的帧吞吐，二者共同约束 <span class=\"formula\">$$B_{\\max}\\approx\\frac{C_{\\mathrm{HBM}}-\\mathrm{VAE}_{\\mathrm{dec}}-\\mathrm{Mem}_{\\mathrm{sys}}}{(\\mathrm{Act}+\\mathrm{KV})_{\\mathrm{blk}}}$$</span>。以 2-SM MMA 与 tcgen05 路径为例，块内注意力走 TMEM 时激活驻留更紧，但跨块 KV 复用仍需经 HBM 往返，带宽瓶颈落在缓存换入换出而非算力；若把精度压到 NVFP4/FP8，KV 占用下降可换取更大 B，但算子支持不足的档位会退化为软件路径，收益被吃掉。工程判断是：先按最坏重叠与最高并发定 B 与缓存深度，再把水位回退做成可观测的显式状态机，而非隐式缩批。</p>\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-28\">二十八 · 块粒度连续批处理：把“批”下沉到时间块</h3>\n<p>流式视频扩散的天然调度单元不是请求，而是时间块。一个长视频请求被切分为 B 个块，每块携带自己的重叠窗口与缓存依赖，于是连续批处理（continuous batching）的“迭代级调度”在这里变成“块级调度”：调度器在每个块边界重新组批，把不同请求中处于同一采样步、块大小兼容的块拼进同一个 kernel 批次，而不是等整个请求结束再换批。这直接改变了吞吐模型——传统请求级批处理下，短请求被长请求拖住，GPU 空转发生在请求尾部；块级组批把空转摊到块边界，空闲率由最大块时长而非最大请求时长决定。</p>\n<p>机制上，调度器维护一个就绪块队列，按（采样步, 块大小, 重叠窗口）三元组做兼容性分组，只有三者一致的块才能同批执行时空注意力，否则跨块键值复用的索引对不齐。伪代码思路：</p>\n<div class=\"formula\">$$\\text{batch}_t = \\{\\,b \\mid \\text{step}(b)=t,\\ \\text{blk}(b)=s,\\ \\text{ovl}(b)=o\\,\\},\\quad |\\text{batch}_t|\\le \\text{cap}(\\text{Mem}_{\\text{free}})$$</div>\n<p>代价落在显存与带宽两侧：同批块数越多，块级激活 $\\mathrm{Act}_b$ 与跨块 KV $\\mathrm{KV}_b$ 同时驻留，峰值显存近似线性上升；而时空注意力的跨块键值复用让每块的 KV 读取量随批内块数增长，HBM 带宽成为硬约束。工程判断是：块级组批的收益不在单块延迟，而在把 VAE 解码与采样步的交错填满——当一个请求在解码块 $b$ 时，另一个请求的块 $b+1$ 正在做注意力，SM 不空转。举例：NVL72 单节点上并行跑多条 720p 长视频请求，若按请求级组批，解码阶段 GPU 利用率塌陷；按块级组批，解码块与采样块可共存于同一时间窗，代价是调度器必须为每个块保留独立的缓存句柄，句柄元数据本身占用显存，块越小元数据开销占比越高。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-29\">二十九 · Chunked prefill 的变体：预填与采样步的交错</h3>\n<p>LLM 里的 chunked prefill 是把长 prompt 切成小段与 decode 交错，避免 prefill 独占 SM 造成尾延迟尖峰。视频扩散没有“prefill/decode”二分，但有结构同构的阶段：首块的时空注意力建立跨块 KV 基座，后续块是增量采样。于是可以把首块（或前若干块）视为“预填”，按更小的 chunk 切分并与后续块的采样步交错执行，让长视频请求在建立 KV 基座的同时不阻塞其他请求的增量步。</p>\n<p>机制上，调度器为每个请求维护一个“基座进度”指针，首块未完成时不参与块级组批，而是以细粒度 chunk 插入到其他批次的空隙；基座完成后请求转入常规块流。代价是首块的重复读取：chunk 切分让同一块的潜变量被多次加载，带宽开销上升，且跨 chunk 的注意力需要保留部分中间特征，缓存管理复杂度提高。公式上，交错带来的有效吞吐可写成：</p>\n<div class=\"formula\">$$\\text{Thr}_{\\text{eff}} = \\frac{\\sum_b \\text{Work}_b}{\\max_t \\text{SM}_{\\text{busy}}(t)},\\quad \\text{尾延迟}\\approx \\max_b(\\text{wait}_b)+\\text{chunk}_{\\text{last}}$$</div>\n<p>具体例子：一条 4K 长视频请求的首块注意力若独占执行，会让同批其他请求的块间等待时间被拉长到首块时长量级；把首块切成若干 chunk 与增量块交错后，尾延迟由最长 chunk 而非最长首块决定。这里的关键取舍是 chunk 太小则跨 chunk 缓存碎片化、带宽浪费，chunk 太大则交错失去意义——调度器需按显存水位与块间等待时间联合定档，材料未给出阈值，工程上应以“chunk 时长不超过当前批内最长块时长”为约束反推。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-30\">三十 · 优先级与抢占：SLO 驱动的块级调度</h3>\n<p>流式输出的 SLO 不是端到端时延，而是块间等待时间——观众感知的是帧流的连续性，而非整段视频何时完成。因此优先级应挂在块上而非请求上：交互式预览请求的块获得高优先级，离线批量渲染的块可被抢占。抢占的粒度也是块：被抢占的块释放其激活与 KV 缓存，保留跨块中间特征句柄以便恢复，恢复时从最近的缓存检查点重入，而非从头重算。</p>\n<p>机制上，调度器按（优先级, 已等待块数, 缓存占用）排序就绪块，显存水位越过阈值时触发抢占，选择缓存占用最大且优先级最低的块驱逐。代价是重算：被驱逐块的跨块 KV 若未落盘则需重建，重建成本等于该块及其依赖块的注意力前向；若落盘到主机内存，则引入 PCIe 往返带宽开销，且恢复时的缓存一致性需要校验。公式上，抢占的净收益取决于重算成本与等待收益的比较：</p>\n<div class=\"formula\">$$\\text{Gain}_{\\text{preempt}} = \\Delta\\text{SLO}_{\\text{high}} - \\big(\\text{Recompute}_b + \\text{Reload}_{\\text{KV}}\\big)$$</div>\n<p>具体例子：NVL72 上同时服务交互式与离线两类视频请求，交互式请求的块间等待目标以帧间隔计，离线请求无硬约束；当显存水位逼近部署档位上限，驱逐离线请求的块可让交互式块立即入批，代价是离线块恢复时重算其重叠窗口内的注意力。工程判断是：抢占必须与重叠窗口联动——重叠越大，恢复时重算的窗口越宽，抢占越不划算，因此高优先级请求应配小重叠，低优先级请求配大重叠以摊薄重算。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-31\">三十一 · 分离式预填/解码在视频扩散里的映射</h3>\n<p>LLM 的 PD 分离把计算密集的 prefill 与带宽密集的 decode 放到不同资源池，视频扩散的对应物是“注意力基座构建”与“块流式采样+VAE 解码”的分离。前者吃算力与跨块 KV 写入带宽，后者吃 HBM 读取带宽与解码器占用；把两者混在同一 SM 池会让算力与带宽互相争抢，分离后各自按最优批大小组批。</p>\n<p>机制上，基座节点负责首块及跨块 KV 的生成与缓存，把 KV 与中间特征通过 NVLink 或 NIXL 传到采样节点；采样节点按块推进采样步并做块级 VAE 解码，流式输出帧。代价是传输：跨块 KV 的体积随块大小与重叠窗口增长，传输带宽成为分离的瓶颈，且 KV 在传输途中的精度格式需与采样节点算子一致，否则需转换开销。公式上，分离的可行性条件是传输时间不超过采样节点的块处理时间：</p>\n<div class=\"formula\">$$\\frac{\\text{KV}_b + \\text{Feat}_b}{\\text{BW}_{\\text{link}}} \\le T_{\\text{sample}}(b)$$</div>\n<p>具体例子：GB200 NVL72 内 NVLink 5 的高带宽让 KV 传输可被块处理时间掩盖，分离收益体现在采样节点不必为基座算力预留 SM；跨节点则传输时间可能主导，此时应退化为同节点分池而非跨节点分离。工程判断是：分离的粒度应与块大小对齐——块越小，KV 传输越频繁、单次体积越小，链路利用率下降；块越大，传输越集中但采样节点等待越久，尾延迟上升。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-32\">三十二 · 尾延迟的压缩：重叠窗口与批大小的联合定档</h3>\n<p>尾延迟在流式视频里由三部分构成：块间等待、最后一块的采样与解码、以及抢占恢复的重算。压缩尾延迟不能只调批大小，必须与重叠窗口联合定档。重叠窗口增大降低块间依赖的等待（跨块 KV 更完整，块可更早启动），但引入重复计算，抬高单块时长与显存；批大小增大提升吞吐但抬高显存水位，触发抢占反而拉长尾延迟。</p>\n<p>机制上，调度器以显存水位为约束、以块间等待时间为目标做二维搜索：水位高时先缩批再增重叠（增重叠换稳定时延），水位低时先减重叠再扩批（减重复计算换吞吐）。代价是搜索本身的调度开销与抖动：频繁定档会让批组成不稳定，跨块缓存句柄反复分配释放。公式上，尾延迟的近似表达为：</p>\n<div class=\"formula\">$$\\text{Tail} \\approx \\underbrace{\\max_b \\text{wait}_b}_{\\text{组批}}+\\underbrace{T_{\\text{ovl}}(o)}_{\\text{重复计算}}+\\underbrace{T_{\\text{VAE}}(b_{\\text{last}})}_{\\text{末块解码}}$$</div>\n<p>具体例子：长视频末块解码往往是尾延迟尖峰，因为此时批内其他请求已陆续完成、批变小、解码器利用率低；把末块解码与下一请求的首块基座交错，可把尖峰摊平，代价是末块帧输出被延迟一个 chunk。工程判断落在具体机制上：尾延迟的压缩本质是用重叠窗口买确定性、用批大小买吞吐，两者在显存水位约束下此消彼长，调度器必须在每个块边界重新求解，而非在请求入口一次性定档——因为块级缓存占用随流式推进单调变化，入口处的静态配置在长视频后段必然失配。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-33\">三十三 · 块粒度调度在并发下的失效边界</h3>\n<p>该方案的调度单元是时间块而非请求，这决定了它与连续批处理（continuous batching）的天然错位：连续批处理靠逐 token 迭代插入新请求来填满算力，而流式视频扩散的每个块必须等前一块的跨块缓存就绪才能进入时空注意力，块间存在硬依赖。因此调度器只能做“块级批”而非“迭代级批”，并发请求数上升时，批内块大小与重叠窗口成为唯一可调旋钮。按公式 <span class=\"formula\">$$\\mathrm{Mem}_{\\mathrm{peak}} \\approx \\sum_{b=1}^{B}\\big(\\mathrm{Act}_{b}+\\mathrm{KV}_{b}\\big)+\\mathrm{VAE}_{\\mathrm{dec}}$$</span>，显存水位随并发块数线性抬升，调度器缩小批大小换稳定时延，代价是单卡吞吐下降——这是该方案在 QPS 升高时最先暴露的边界：批缩到 1 时流式管线退化为串行，块间等待时间直接暴露为尾延迟。</p>\n<p>失效条件可以具体化为三条。其一，重叠窗口增大虽能缓解块边界接缝，但重叠部分被重复前向，重复计算量正比于重叠帧数与块数之比，长视频下这部分开销不可忽略，且它不产生任何新输出，纯粹是显存与时延的税。其二，跨块缓存复用要求上一块的 KV 与中间特征在下一块计算期间驻留，若并发请求共享同一显存池，缓存淘汰策略与批调度耦合，容易出现“为保 SLO 缩批→缓存命中率下降→重复前向增多→时延反而上升”的反向反馈。其三，精度与显存策略依赖硬件算子支持，低精度格式在跨档位迁移时需重新验证，材料未给出可移植性结论，工程上应视为不可默认继承的假设。</p>\n<table class=\"mini\"><thead><tr><th>并发档位</th><th>调度动作</th><th>主要代价</th><th>尾延迟风险</th></tr></thead><tbody><tr><td>低并发</td><td>大块、小重叠、满批</td><td>峰值显存高</td><td>低，块间等待短</td></tr><tr><td>中并发</td><td>缩批、适度增重叠</td><td>重复计算上升</td><td>中，缓存争用</td></tr><tr><td>高并发</td><td>批降至 1、回退小分块</td><td>吞吐塌缩、串行化</td><td>高，块间等待外露</td></tr></tbody></table>\n<p>压尾延迟的工程判断在于把“块间等待”当作一等指标而非副产品：监控峰值显存的同时必须监控块间空闲时间，二者任一越界都触发回退到更小分块或更低精度。分离式预填/解码的思路在此可借用——把 VAE 解码按块剥离到独立流，使解码与下一块的采样步重叠，用解码的带宽占用换取采样算力的连续占用，从而在不增显存的前提下削掉块边界的串行空档；但这要求解码侧有独立显存配额，否则 <span class=\"formula\">$$\\mathrm{VAE}_{\\mathrm{dec}}$$</span> 会重新计入峰值。该方案未给出阈值与监控指标，落地时需自行标定块间等待的 SLO 预算，并把重叠窗口设为可在线调整的参数而非静态配置。</p>\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-34\">三十四 · 切分维度与流式块的对齐</h3>\n<p>在 Blackwell 档位上谈并行，第一步不是选 TP 还是 EP，而是先问：被切分的那条轴和流式推理的时间块轴是否正交。视频扩散的推理负载有一条天然的时间维（块序列）和一条模型维（层、头、专家）。数据并行（DP）沿请求轴复制，每张卡持有完整权重、各自推进自己的块序列，通信只发生在权重同步与梯度——推理期几乎为零，代价是权重副本占用显存。张量并行（TP）沿隐藏维与头维切分，每层注意力与前馈都要做 All-Reduce 或 Reduce-Scatter，通信量与激活规模成正比，落在 NVLink 5 域内尚可承受，一旦跨节点就变成主导项。流水并行（PP）沿层切分，把不同层放到不同卡上，代价是流水气泡——块与块之间必须填充，而视频扩散的块推进本来就是串行的，气泡会被放大。专家并行（EP）只在 MoE 结构里成立，走 All-to-All，是四类切分里通信形态最不规则的一种。</p>\n<p>流式推理的关键约束是：块间缓存（跨块键值与中间特征）必须和产生它的那组卡绑定。若把缓存管理放在 TP 组内，键值按头切分后天然分布在各卡上，复用时不需搬运；若把块调度放在 DP 组间做负载均衡，则缓存无法跨卡迁移，只能整块重算。这就决定了调度器的切分策略：<strong>块轴走 DP，模型轴走 TP/PP，缓存跟随模型轴</strong>。一个具体例子：8 卡 NVLink 域内做 TP=8 的单请求长视频，每块注意力后一次 All-Reduce，块大小决定单次通信的字节数；若改成 DP=8 各跑一条请求，通信归零但每卡要装下完整权重与完整块缓存，显存峰值按块数线性上升。论文的显存公式</p>\n<div class=\"formula\">$$\\mathrm{Mem}_{\\mathrm{peak}} \\approx \\sum_{b=1}^{B}\\big(\\mathrm{Act}_{b}+\\mathrm{KV}_{b}\\big)+\\mathrm{VAE}_{\\mathrm{dec}}$$</div>\n<p>在 DP 下 B 是每卡独立块数，在 TP 下 B 是全局块数而每卡只存 1/TP 的 KV——切分维度的选择直接改写这个求和的上限。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-35\">三十五 · NVLink 5 与 NVSwitch：域内通信的物理上限</h3>\n<p>GB200/GB300 NVL72 把 72 颗 GPU 放进一个 NVLink 域，NVSwitch 提供全互联而非胖树收敛，这意味着域内任意两卡之间的带宽是对称的，All-Reduce 的环状算法不再受“跨脊交换机”的层级惩罚。对推理的意义在于：TP 组可以跨 8 卡甚至更大而不至于让通信成为每层的固定税。但物理上限仍是上限——All-Reduce 的耗时下界由消息大小与链路带宽决定，环状算法的传输量为</p>\n<div class=\"formula\">$$V_{\\mathrm{AR}} = 2\\cdot\\frac{N-1}{N}\\cdot S$$</div>\n<p>其中 S 是单次归约的激活字节数，N 是组内卡数。N 增大时 V 趋近 2S，收益递减；这就是 TP 超过一定宽度后每 token 时延不再下降的原因。视频扩散的激活比语言模型更“胖”：时空注意力的键值张量按块内帧数×空间分辨率展开，单块激活可达数百 MB 量级，一次 All-Reduce 就是实打实的带宽消耗。工程判断是：<strong>把 TP 宽度压在 NVLink 域内、把块大小调到让单次通信落在带宽可隐藏的区间</strong>。若块太小，通信次数多、每次消息小，启动开销占比高；若块太大，单次消息超出可重叠窗口，计算与通信无法流水。调度器增大重叠窗口换取时延稳定，本质上也是在给通信留出重叠余量。</p>\n<p>All-to-All 在 EP 下更苛刻：它是非对称的、按 token 路由的稀疏通信，NVSwitch 的全互联能降低尾延迟，但路由不均时会出现热点卡。视频扩散若采用 MoE 化的时空骨干，块内 token 在时间维上高度相关，路由容易聚集到少数专家，形成 All-to-All 的长尾。代价体现在块间等待时间上——这正是论文用块间等待作为 SLO 指标的原因之一。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-36\">三十六 · NIXL 传输：把缓存搬运从计算路径上摘出去</h3>\n<p>NIXL 解决的是另一类通信：不是层内的集合通信，而是块缓存、权重分片、VAE 解码输入在卡间与节点间的点对点搬运。它的价值在于把传输描述与执行解耦——注册内存区域、建立传输描述符，然后由底层后端（NVLink、RDMA、或节点内拷贝引擎）异步完成，计算流不必同步等待。对流式推理，这对应一个具体机制：块 b 采样完成后，其键值与中间特征不必立刻复制到下一段的持有卡，而是登记为可复用缓存，等块 b+1 的注意力算子真正需要时再拉取。这样传输被隐藏在下一块的计算窗口里。</p>\n<p>代价模型很直接：若每块缓存大小为 C 字节、链路有效带宽为 W，则单块搬运时间为 C/W；当 C/W 超过块计算时间 T_comp 时，传输暴露在关键路径上，块间等待时间上升，SLO 被击穿。工程上的做法是让重叠窗口承担双重职责——既复用跨块键值减少重复注意力，又为缓存搬运提供时间窗口。但重叠本身引入重复计算，论文明确指出这是时延与显存的权衡：重叠越大，重复前向越多，计算时间 T_comp 上升，反而可能让 C/W 重新变得可隐藏。这是一个非单调的调参面，调度器按显存水位调整重叠窗口时，实际上是在这个面上找局部最优点。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-37\">三十七 · 通信何时成为瓶颈：三个判据</h3>\n<p>不要把“通信慢”当成笼统结论，要落到可判定的判据上。第一条判据是<strong>计算通信比</strong>：单块计算量（FLOPs）除以单块通信量（字节），若该比值低于硬件的算力带宽比，通信就是瓶颈。视频扩散的时空注意力在块内帧数大时计算密度高，在块边界处因重叠而重复计算，密度反而下降——块边界是通信最易暴露的位置。第二条判据是<strong>集合通信的组规模与消息大小的匹配</strong>：小消息高频次时启动开销主导，大消息低频次时带宽主导，TP 组内存在一个使总时延最小的消息尺寸，块大小应围绕它设计。第三条判据是<strong>All-to-All 的路由偏斜度</strong>：最大卡负载与平均负载之比超过阈值时，尾延迟决定块间等待，此时增加卡数无益，应改路由或改切分。</p>\n<table class=\"mini\"><thead><tr><th>切分</th><th>通信原语</th><th>瓶颈形态</th><th>对流式块的影响</th></tr></thead><tbody><tr><td>DP</td><td>几乎无（推理期）</td><td>显存副本</td><td>缓存不可跨卡迁移，整块重算</td></tr><tr><td>TP</td><td>All-Reduce / Reduce-Scatter</td><td>激活字节×层数</td><td>块边界重复计算拉低计算通信比</td></tr><tr><td>PP</td><td>点对点激活传递</td><td>流水气泡</td><td>块串行推进放大气泡</td></tr><tr><td>EP</td><td>All-to-All</td><td>路由偏斜长尾</td><td>块间等待时间直接受尾延迟支配</td></tr></tbody></table>\n<p>具体例子：一条长视频在 TP=8 的 NVLink 域内推进，块内注意力后 All-Reduce 的激活为 S，若块大小使 S 落在带宽主导区，则单层通信时间约 2S/W；当重叠窗口增大导致块边界重复前向，有效计算时间被摊薄，同样的 S 对应的计算通信比下降，通信从可隐藏变为暴露。此时调度器的正确动作不是继续加卡，而是缩小批大小以降低并发块数、或减小重叠窗口以恢复计算密度——这与论文“显存水位升高时缩小批大小或增大重叠”的策略在方向上并不总是一致，说明重叠窗口的调整必须同时看通信暴露度，而不只看显存。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-38\">三十八 · 把通信代价纳入块调度</h3>\n<p>流式推理的调度器若只监控峰值显存与块间等待时间，会漏掉通信侧的早期信号。可操作的机制是把每次集合通信的耗时与块计算耗时分别打点，计算二者的比值作为隐藏度指标；当隐藏度低于阈值时，优先调整块大小而非批大小，因为块大小同时改变消息尺寸与计算密度。伪代码思路：对每个块 b，估计其激活字节 S_b 与计算量 F_b，若 F_b/S_b 低于硬件比值，则将该块与相邻块合并以增大消息、提升密度；若合并后显存峰值超过水位，则退回并在 DP 组间迁移请求而非在 TP 组内加宽。这一决策把切分选择、块大小、重叠窗口三者耦合在一个反馈环里，而不是各自独立调参。</p>\n<p>代价落在功耗与带宽上：NVLink 域内持续高占用的集合通信会推高链路功耗，而流式推理的长尾特性意味着大部分时间链路空闲、少数块边界时突发——这种突发型负载对功耗预算不友好，也让容量规划难以用平均带宽估算。工程判断是：<strong>以块边界的峰值带宽而非平均带宽做容量规划</strong>，并在块调度中预留通信重叠窗口，把突发摊平。论文的材料未给出具体阈值与监控指标，但其以块间等待时间衡量 SLO 的取向，正好对应通信暴露度这一维度；把该指标与隐藏度指标并列，是把并行与通信从“配置项”变成“运行时控制量”的最小改动。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-39\">三十九 · 块粒度流水线在并行切分下的通信边界</h3>\n<p>该方案的并行形态天然偏向 DP 与 PP，而非 TP/EP。原因在于分块调度器以时间块为调度单位，块内时空注意力的键值缓存按块保留、跨块复用，若把单个块的注意力沿头维切到多卡（TP），每步采样都要在块内做 All-Reduce 归约注意力输出，通信量与块内 token 数成正比，而块本身已被切小，归约延迟占比上升；若把不同时间块分给不同卡（PP 式流水），块间存在重叠窗口，重叠区的键值必须跨卡可见，等价于一次 All-Gather 或点对点传输。因此通信是否成为瓶颈，取决于块内计算量与跨块传输量之比：设块内单步计算时间为 <span class=\"formula\">$$T_{\\mathrm{comp}}$$</span>、跨块键值传输时间为 <span class=\"formula\">$$T_{\\mathrm{comm}}=\\frac{S_{\\mathrm{kv}}}{BW_{\\mathrm{link}}}$$</span>，当 <span class=\"formula\">$$T_{\\mathrm{comm}}&gt;T_{\\mathrm{comp}}$$</span> 时流水线退化为通信受限，重叠窗口越大、块越小，这个不等式越容易成立。</p>\n<p>在 NVLink 5 与 NVSwitch 构成的 NVL72 域内，All-to-All 与 All-Reduce 的代价主要由域内带宽与集合通信的同步点决定；NIXL 类点对点传输适合把已完成块的缓存或解码后的帧搬到下游节点，避免全域集合通信。工程判断是：块内注意力优先留在单卡，跨块缓存用点对点搬运而非 All-Gather，批调度按块粒度推进以摊薄同步开销。一旦并发升高、调度器缩小批大小，单块计算量下降而通信量不变，通信占比被动上升，这正是该方案在高压并发下 SLO 抖动的机制来源。</p>\n<table class=\"mini\"><thead><tr><th>切分方式</th><th>主要通信</th><th>何时成为瓶颈</th></tr></thead><tbody><tr><td>DP（块级）</td><td>无集合通信，仅输出汇聚</td><td>块数少、单卡显存先满</td></tr><tr><td>PP（跨块流水）</td><td>重叠区键值点对点</td><td>重叠窗口大、块间等待累积</td></tr><tr><td>TP（块内头维）</td><td>每步 All-Reduce</td><td>块被切小、归约延迟占比高</td></tr></tbody></table>\n<p>失效条件集中在三处：重叠窗口增大换取输出连续性时，重复计算与跨卡键值传输同时上升，时延与显存权衡被低估；并发升高触发缩批，块间等待时间成为 SLO 主导项而材料未给出阈值与监控指标；精度与显存策略依赖硬件算子支持，跨档位迁移需重新验证通信与缓存布局。可操作的回退是缩小分块、降低重叠或改走点对点传输，把集合通信从关键路径上移出。</p>\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-40\">四十 · 精度塌陷：从“格式合法”到“数值不可用”的分界</h3>\n<p>流式推理把采样切成时间块，块内与跨块键值复用让同一份缓存被反复读取，于是数值误差不再是一次算子的局部噪声，而是沿时间轴累积的状态污染。NVFP4/FP8 在 Blackwell 上的 tcgen05 路径里，量化误差主要来自两处：块内激活的动态范围估计，以及跨块 KV 复用时旧块键值以低精度驻留、被新块反复加权。前者是逐块重标定问题，后者是缓存精度与新鲜度问题。工程上要区分“格式合法”与“数值可用”：前者指算子跑通、无 NaN/Inf，后者指块间过渡处不出现色带、闪烁、纹理漂移。</p>\n<p>诊断手段不是看单帧 PSNR，而是沿时间轴取块边界处的差分序列。设第 b 块输出为 <span>O<sub>b</sub></span>，重叠窗口长度为 <span>w</span>，则过渡区误差可写成：</p>\n<div class=\"formula\">$$E_{\\mathrm{seam}}=\\frac{1}{w}\\sum_{t\\in \\mathcal{W}_{b}}\\big\\|O_{b}(t)-O_{b-1}(t)\\big\\|_{2}^{2}$$</div>\n<p>当 <span>E<sub>seam</sub></span> 在若干连续块上单调上升，说明跨块缓存的低精度驻留正在放大误差，而非单块量化噪声。此时回滚顺序应是：先把跨块缓存恢复到更高精度格式（仅缓存，不动算子），再考虑整块回退到 FP8。代价上，缓存精度每升一档，KV 占用按位宽比例上升，直接压缩可并发的块数；在显存水位接近上限时，这会触发调度器缩批，吞吐下降。具体例子：一段长视频在 FP4 缓存下块边界出现周期性色偏，把跨块 KV 改为 FP8 驻留、块内激活仍走 FP4，色偏消失而峰值显存上升一档，调度器随之把批大小下调以维持水位。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-41\">四十一 · OOM 的真实来源：峰值公式里的隐藏项</h3>\n<p>论文给出的峰值显存模型是块级激活、KV 与 VAE 解码器之和：</p>\n<div class=\"formula\">$$\\mathrm{Mem}_{\\mathrm{peak}} \\approx \\sum_{b=1}^{B}\\big(\\mathrm{Act}_{b}+\\mathrm{KV}_{b}\\big)+\\mathrm{VAE}_{\\mathrm{dec}}$$</div>\n<p>这个式子容易被误读为“逐块累加”，实际部署中 OOM 往往不来自稳态项，而来自三个隐藏项：重叠窗口使相邻块同时驻留、VAE 解码与采样步并发时的临时缓冲、以及批内多请求的块推进不同步造成的“块相位差”。当批内请求的块边界不对齐，调度器为等待慢请求而保留已完成块的缓存，<span>KV<sub>b</sub></span> 的实际驻留量超过公式假设。定位方法是给每个块打上生命周期标签（分配、采样中、待解码、可释放），监控“待解码但未释放”的块数；该计数持续上升即为 OOM 前兆，而非瞬时峰值。</p>\n<p>回滚策略按代价从低到高：先增大重叠窗口换取更平滑的块推进（代价是重复计算上升、时延增加），再缩小批大小（吞吐下降但水位立刻回落），最后回退到更小分块（块数增多、跨块缓存管理开销上升）。注意增大重叠与缩小批在方向上相反：前者增加单请求驻留，后者减少并发驻留，混用会让水位震荡。工程判断是：OOM 前兆出现时只动一个旋钮，并观察块间等待时间是否同步恶化，以此区分“真显存不足”与“调度相位错位”。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-42\">四十二 · 批抖动与尾延迟：块粒度调度的固有代价</h3>\n<p>流式输出对批调度敏感，根源在于批是按块粒度推进的：一个批内所有请求必须等到最慢请求的当前块完成，才能一起进入下一块。这使尾延迟不由平均块时延决定，而由批内块时延的分布上尾决定。设批内请求的块时延为 <span>τ<sub>i</sub></span>，批推进时间为 <span>max<sub>i</sub> τ<sub>i</sub></span>，则批抖动可量化为批推进时间的变异系数；当并发升高、批内请求的视频长度差异变大时，该变异系数上升，表现为块间等待时间锯齿状波动。</p>\n<p>监控上应把“块间等待时间”与“批内块时延方差”分开采集：前者反映调度器等待，后者反映请求异质性。若方差主导，缩小批只是把抖动摊薄而非消除；正确做法是按块相位分组，把处于相同块索引的请求聚成批，减少跨相位等待。代价是分组本身引入排队延迟，且分组粒度越细、批利用率越低，吞吐下降。具体例子：混合长短视频的并发流中，短请求频繁等待长请求的块完成，尾延迟抬升；改为按已推进块数分桶后，短请求独立成批，尾延迟收敛，但 GPU 利用率因批变小而下降，需在 SLO 与吞吐间取平衡。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-43\">四十三 · 静默降级：没有报错的性能与质量滑坡</h3>\n<p>最危险的失败模式不是崩溃，而是系统仍在输出、指标仍在“正常”区间，但质量或时延已悄然劣化。流式管线里有三条静默降级路径：其一，调度器因显存水位反复缩批，单请求块推进变慢，端到端时延上升但无错误；其二，跨块缓存因显存压力被提前释放，后续块被迫重算，重复计算上升而输出看似连续；其三，精度回退被自动触发后未复位，长期停留在低精度路径，块边界误差缓慢累积。三者共同特征是：错误率为零，但 SLO 指标漂移。</p>\n<p>对策是把“降级动作”本身变成一等监控对象：每次缩批、每次缓存提前释放、每次精度回退都打点计数，并与块间等待时间、<span>E<sub>seam</sub></span> 联动。设降级计数为 <span>D</span>，则可用一个简单的漂移判据：当 <span>D</span> 在滑动窗口内单调上升且 <span>E<sub>seam</sub></span> 同步上升，判定为静默降级而非负载波动。回滚必须显式：精度回退需在显存水位回落后主动复位，缓存释放策略需在批相位对齐后恢复，否则系统会“卡”在降级态。代价是复位动作本身带来一次水位尖峰，需在低并发窗口执行。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-44\">四十四 · 监控面与定位顺序：从水位到块边界的排查链</h3>\n<p>把上述失败模式落到可执行的监控面，需要四个层次的指标：显存层（峰值、待解码未释放块数）、调度层（批大小、块相位分布、块间等待时间）、数值层（块边界差分、精度回退计数）、输出层（流式帧的连续性）。定位顺序应固定为：先看显存层是否触发缩批，再看调度层是否相位错位，再看数值层是否缓存精度不足，最后才怀疑算子本身。这个顺序的依据是代价：前两层是调度与缓存问题，回滚成本低；后两层涉及精度与算子，回滚成本高且影响面大。</p>\n<p>表格给出各失败模式的主指标与首选回滚动作，阈值一栏留空是因为材料未给出具体数字，部署时需按硬件档位自行标定：</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>主监控指标</th><th>首选回滚</th><th>代价</th></tr></thead><tbody><tr><td>精度塌陷</td><td>块边界差分 <span>E<sub>seam</sub></span></td><td>跨块缓存升精度</td><td>KV 占用上升、并发块数下降</td></tr><tr><td>OOM</td><td>待解码未释放块数</td><td>缩批或增大重叠（只动一个）</td><td>吞吐下降或重复计算上升</td></tr><tr><td>批抖动</td><td>批内块时延方差</td><td>按块相位分桶</td><td>批利用率下降</td></tr><tr><td>尾延迟</td><td>块间等待时间上尾</td><td>缩小批或拆批</td><td>吞吐下降</td></tr><tr><td>静默降级</td><td>降级计数 <span>D</span> 与 <span>E<sub>seam</sub></span> 联动</td><td>显式复位精度与缓存策略</td><td>复位瞬间水位尖峰</td></tr></tbody></table>\n<p>定位链的关键在于“只动一个旋钮并观察联动指标”。例如缩批后若块间等待时间未改善而待解码块数下降，说明问题是驻留而非调度；若两者同时恶化，说明批相位错位才是主因，应转向分桶而非继续缩批。这种单变量排查在流式管线里比端到端重跑更省时，因为每次重跑都伴随缓存重建与块相位重置。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-45\">四十五 · 回滚的工程边界：可移植性与跨档位重验</h3>\n<p>精度与显存策略依赖硬件算子支持，跨档位迁移需重新验证，这意味着回滚方案不能假设同一套阈值在 B200 与 GB200 NVL72 上通用。SM100/SM103 的 tcgen05 路径与 TMEM 占用决定了低精度算子的实际吞吐收益，当算子不支持某格式时，回退到更高精度不是“保守选择”而是“唯一可跑路径”，此时监控应把“格式支持探测”作为启动期检查项，而非运行期被动回退。回滚的工程边界因此是：格式回退必须与分块大小、重叠窗口联合重标定，因为块级激活的驻留量随精度变化，原分块在低精度下可能已不满足水位约束。</p>\n<p>最后落在具体机制上：把回滚做成块粒度的状态机，每个块携带精度标签与缓存新鲜度标签，调度器在块推进时检查标签一致性，不一致则在该块边界处切换而非整条管线重启。这样回滚代价被限制在单个块的重复计算内，而不是整段视频重跑；代价是状态机本身增加调度开销，且标签切换点可能引入一次块边界误差尖峰，需与 <span>E<sub>seam</sub></span> 监控联动确认尖峰可接受。工程判断是：回滚粒度越细，静默降级的暴露越早，但状态管理成本越高，二者需按 SLO 严格程度取舍。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-46\">四十六 · 流式管线的失效边界：从块级水位到静默降级的诊断路径</h3>\n<p>流式推理的显存峰值由块级激活与跨块缓存共同决定，<span class=\"formula\">$$\\mathrm{Mem}_{\\mathrm{peak}} \\approx \\sum_{b=1}^{B}\\big(\\mathrm{Act}_{b}+\\mathrm{KV}_{b}\\big)+\\mathrm{VAE}_{\\mathrm{dec}}$$</span> 意味着一旦调度器把块大小或重叠窗口调大，峰值显存不是线性上升而是按块累加，OOM 往往发生在第 b 块采样中途而非请求入口。诊断时应把监控点打在块级：每块采样前后的显存水位、块间等待时间、VAE 解码阶段的瞬时占用。块间等待时间突然拉长而显存水位未降，说明重叠窗口带来的重复时空注意力前向已经吃掉了带宽预算，此时缩小批大小只能缓解排队，不能消除重复计算，正确动作是回退到更小的重叠窗口并重新验证输出连续性。</p>\n<p>批抖动与尾延迟是同一枚硬币的两面。流式输出按块解码帧，调度器依据显存水位缩小批大小以维持 SLO，但并发升高时批大小的阶跃变化会让块间等待时间出现尖峰，尾延迟由最慢的那一块决定而非平均块。工程上应把批大小调整做成带滞回的连续量，并记录每次调整前后的块间等待分布；若调整后尾延迟未收敛，说明瓶颈已从显存转向跨块缓存的读写带宽，继续压批只会浪费算力。精度塌陷则更隐蔽：低精度算子与 KV 缓存格式的收益受硬件档位与算子支持限制，跨档位迁移时数值误差会在多步采样中累积，表现为输出帧的纹理漂移而非报错。监控应在块级比对相邻块重叠区域的帧差，帧差异常放大即为精度塌陷的早期信号，回退路径是切回更高精度的算子格式并重新校准缓存占用。</p>\n<p>静默降级是最难定位的一类：调度器为保住 SLO 自动增大重叠或缩小批，系统不报错但吞吐与显存效率同时下滑，表现为块间等待时间缓慢爬升、峰值显存贴着上限运行。诊断需要把调度决策本身作为指标暴露出来——每次批大小与重叠窗口的变更、变更前后的块间等待与峰值显存，形成可回溯的决策日志。回滚策略应分级：先回退重叠窗口，再回退批大小，最后回退精度格式，每一级都需重新验证输出连续性与峰值显存是否回到可部署档位。跨档位迁移时，精度与显存策略必须重新验证而非直接复用，因为算子支持差异会让同一配置在不同 Blackwell 档位上给出不同的失败模式。</p>\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-47\">四十七 · 基准口径的三层结构：模型、硬件档位、负载</h3>\n<p>读这篇流式推理论文的“结果”之前，必须先承认一件事：材料没有给出数据集、基线名称与任何实验数字，结论停留在机制层面。因此本部分的重点不是复述某个加速比，而是建立一套可复用的口径框架，让工程读者在拿到任何一组视频扩散推理数字时，能判断它属于哪一层、和谁可比。口径分三层：模型层（视频扩散或流匹配模型的采样步数、潜变量分辨率、时长与帧率）、硬件档位层（Blackwell 的 SM100/SM103 两档，B200/B300 单卡与 GB200/GB300 NVL72 机架两种形态，显存容量与功耗包络不同）、负载层（batch 大小、并发请求数、块大小与重叠窗口）。三层中任何一层变动，峰值显存与时延都会移动，跨层直接比较加速比是无效的。</p>\n<p>论文的显存模型给出了口径的锚点：</p>\n<div class=\"formula\">$$\\mathrm{Mem}_{\\mathrm{peak}} \\approx \\sum_{b=1}^{B}\\big(\\mathrm{Act}_{b}+\\mathrm{KV}_{b}\\big)+\\mathrm{VAE}_{\\mathrm{dec}}$$</div>\n<p>这个式子说明峰值显存是块级激活、块级 KV 缓存与 VAE 解码器占用之和，B 为同时在推进的块数（与 batch、并发、重叠窗口共同决定）。它同时是一个口径声明：任何声称“显存降低”的数字，必须说明是降低了哪一项——是缩小了 B（调度层），还是压缩了 Act/KV 的数值格式（精度层），还是把 VAE 解码改成按块流式从而削掉了整段解码的驻留（结构层）。三者不可互相替代，也不可混算成一个百分比。</p>\n<ul>\n<li>模型层：采样步数与时长决定总前向次数，是时延的分母；不同模型的步数不同，TPOT 类指标不可跨模型比。</li>\n<li>硬件档位层：单卡与 NVL72 机架的显存容量与带宽包络差异决定了块大小与重叠窗口的可选范围，同一策略在两档上的最优参数不同。</li>\n<li>负载层：batch 与并发决定 B 的实际取值，是吞吐与 SLO 的直接杠杆。</li>\n</ul>\n<p>具体例子：一个长视频请求被切成若干时间块，块大小固定、重叠窗口设为若干帧。重叠窗口增大时，跨块复用的键值命中率上升、重复前向减少，但每块的计算量与激活占用上升；在单卡档位上这可能直接把 B 压到 1，吞吐塌陷，而在 NVL72 档位上同样的重叠窗口仍能维持多块并行。这就是“同一组数字在不同硬件档位不可比”的最直接来源。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-48\">四十八 · 指标定义：TTFT、TPOT、吞吐、显存、功耗各自测什么</h3>\n<p>视频扩散的指标语义与 LLM 服务不同，必须重新定义，否则会把不同东西塞进同一个名字。TTFT（首帧时间）在本方案中对应“首个时间块完成采样并完成 VAE 解码、输出第一批帧”的时刻，它包含块切分、首块前向与首块解码，受块大小与重叠窗口直接影响：块越大，首块前向越重，TTFT 越长；重叠越大，首块需要预填的上下文越多。TPOT 类比为“块间间隔”，即相邻两块输出之间的时间，它由单块采样步数、跨块缓存命中率与调度等待共同决定，是流式输出连续性的直接度量。吞吐应区分两种口径：帧吞吐（每秒输出帧数）与请求吞吐（每秒完成的视频请求数），前者对块粒度敏感，后者对并发与批调度敏感，二者在并发升高时走向相反。</p>\n<p>显存指标要分峰值与稳态：峰值由上面的公式给出，稳态则由缓存驻留决定——已完成块的缓存被释放，但未完成块与重叠窗口保留的键值仍在占用。功耗指标在 Blackwell 档位上与显存带宽利用率强相关，视频扩散的时空注意力是带宽密集型，功耗包络会反过来限制可持续的 batch 与重叠组合。工程上应把“峰值显存 / 块间等待时间”作为一对联合监控量，因为调度器正是依据显存水位调整批大小与重叠窗口的：显存水位升高时缩小批或增大重叠以换取稳定时延，这一策略的代价是吞吐下降，必须在指标上同时体现，不能只报时延改善。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>本方案中的语义</th><th>主要敏感因素</th><th>常见误读</th></tr></thead><tbody><tr><td>TTFT</td><td>首块采样+解码完成、首批帧输出</td><td>块大小、重叠窗口、首块预填</td><td>与 LLM 的 token 级 TTFT 直接对比</td></tr><tr><td>块间间隔</td><td>相邻块输出之间的时间</td><td>缓存命中率、调度等待</td><td>当作恒定值，忽略并发下的抖动</td></tr><tr><td>帧吞吐</td><td>每秒输出帧数</td><td>块粒度、VAE 解码并行度</td><td>与请求吞吐混为一个数</td></tr><tr><td>峰值显存</td><td>块级激活+KV+VAE 占用上界</td><td>B、数值格式、重叠</td><td>把稳态值当峰值报</td></tr><tr><td>功耗</td><td>带宽密集期的可持续包络</td><td>注意力带宽利用率、batch</td><td>忽略它反过来约束 batch</td></tr></tbody></table>\n<p>具体例子：并发从低到高爬升时，调度器缩小批以压显存水位，帧吞吐可能先升后平，而块间间隔的尾部（p99）开始拉长；此时若只报平均块间间隔，会掩盖流式输出在并发下的 SLO 风险。论文材料明确说流式输出对批调度敏感、并发升高时 SLO 稳定性缺乏数字支撑，这正是口径必须把尾延迟单列的原因。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-49\">四十九 · 哪些提升不可比：五类常见的错位比较</h3>\n<p>第一类错位是精度层与调度层混算。论文的精度与显存策略围绕算子数值格式与 KV 缓存占用展开，但未给出具体量化方案；若一组数字同时包含低精度算子带来的带宽节省与分块调度带来的激活压缩，就不能把它归因于“流式推理”本身。第二类是重叠窗口不同。重叠引入重复计算，是时延与显存权衡的直接旋钮；重叠窗口大的配置显存峰值高、重复前向多，但跨块复用命中率高、输出连续性更好，与重叠窗口小的配置比加速比没有意义。第三类是 batch 与并发口径不同：按块粒度组织的批与按请求组织的批，在同一并发下 B 的取值不同，峰值显存与吞吐都不可直接对齐。</p>\n<p>第四类是硬件档位跨越。单卡 B200/B300 与 GB200/GB300 NVL72 的显存容量与带宽包络不同，同一分块策略在两档上的最优块大小与重叠窗口不同；论文材料明确说精度与显存策略的收益受硬件档位与算子支持限制、跨档位可移植性未验证，因此跨档位报同一个加速比属于口径错误。第五类是基线缺失下的“相对提升”。材料说明未给出基线，那么任何“比某方案快多少”的表述都只能是机制层面的定性判断，不能进入容量规划。工程判断上，应要求任何一组数字附带四元组标注：模型与步数、硬件档位与形态、batch/并发/块大小/重叠窗口、指标定义（峰值还是稳态、平均还是尾延迟）。缺任一项即视为不可比。</p>\n<ul>\n<li>可比的充分条件：同一模型与采样步数、同一硬件档位与形态、同一负载四元组、同一指标定义。</li>\n<li>不可比但可参考：机制相同、负载不同——只能用于判断趋势方向，不能用于容量估算。</li>\n<li>完全不可比：跨精度层归因、跨档位加速比、无基线的相对百分比。</li>\n</ul>\n<p>具体例子：某配置把重叠窗口从较小值调到较大值，块间重复计算增加，采样时延上升但峰值显存因缓存复用而下降；若把它与另一配置的“时延降低”并列，读者会误以为两者在同一权衡点上。正确读法是把它标为“显存换时延”的移动，而非加速。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-50\">五十 · 消融怎么读：块大小、重叠窗口、缓存复用三旋钮</h3>\n<p>论文的消融围绕块大小、重叠窗口与缓存复用策略展开，考察峰值显存与采样时延的权衡，但具体数字未给出。读这类消融的正确姿势是把它当作参数敏感性分析，而不是性能排名。块大小决定单块前向的激活规模与首块 TTFT；重叠窗口决定跨块键值复用的命中率与重复计算量；缓存复用策略决定已完成块释放的时机与未完成块的驻留上界。三者耦合：块越小，块间等待越频繁、调度开销占比越高；块越大，峰值显存越接近整段解码的驻留，流式输出的连续性收益被削弱。</p>\n<p>伪代码层面的读法是看调度器在显存水位约束下如何联合调整：</p>\n<div class=\"formula\">$$\\text{若 } \\mathrm{Mem}_{\\mathrm{peak}} &gt; \\text{水位阈值}: \\quad \\text{batch} \\downarrow \\ \\text{或} \\ \\text{overlap} \\uparrow; \\quad \\text{目标} \\min\\ \\text{p99 块间等待}$$</div>\n<p>这条规则的代价必须与收益一起读：增大重叠以降显存，实际是把重复计算换成缓存命中，采样时延不一定下降；缩小 batch 以降显存，直接损失吞吐。消融表里若只列峰值显存与平均时延，就遗漏了尾延迟与吞吐这两个真正决定 SLO 的量。工程上应要求消融同时给出四个量：峰值显存、平均块间间隔、p99 块间间隔、帧吞吐，缺一则无法判断该配置是否可部署。</p>\n<p>具体例子：缓存复用策略在“保留上一块键值”与“保留多块键值”之间选择，前者驻留小、命中率低、重复前向多，后者驻留大、命中率高、峰值显存高。在长视频下，后者的显存峰值可能越过水位阈值，触发调度器缩批，最终吞吐反而低于前者——这是消融中最容易被误读的非单调现象，也是论文所说“长视频下时延与显存权衡容易被低估”的具体形态。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-51\">五十一 · 面向容量规划的读法：把机制结论转成可执行判断</h3>\n<p>由于材料未给出数据集、基线与数字，容量规划不能从论文结果直接外推，只能从机制约束出发建立保守边界。第一步是用显存公式反推可行域：给定硬件档位的显存容量，减去 VAE 解码器占用，剩余部分除以单块（Act+KV）的估算占用，得到 B 的上界；B 再与并发、块大小、重叠窗口联立，得到该档位下可支持的并发区间。第二步是用块间等待的尾延迟约束反推重叠窗口的下界：重叠太小则缓存命中率低、重复前向多，块间间隔拉长；重叠太大则显存峰值逼近阈值、触发缩批。第三步是把功耗包络作为可持续性的约束，带宽密集期的功耗会限制 batch 的长期上限，不能只看瞬时峰值。</p>\n<p>这套读法的价值在于它不依赖论文未给出的数字，而是把论文的机制结论（分块流式、跨块缓存、按块 VAE 解码、显存水位调度）转成三条可执行判断：其一，任何“显存降低”必须指明降低的是公式中的哪一项，否则无法在别的档位复现；其二，任何“时延缩短”必须区分首块 TTFT 与块间间隔，前者由块大小主导、后者由缓存命中与调度主导；其三，任何跨档位迁移都必须重新标定块大小与重叠窗口，因为算子支持与显存容量不同，论文明确说跨档位可移植性未验证。</p>\n<ul>\n<li>显存侧：先扣 VAE 驻留，再按单块占用定 B 上界，最后用并发与重叠修正。</li>\n<li>时延侧：TTFT 与块间间隔分开建模，尾延迟单列，不用平均值替代。</li>\n<li>吞吐侧：帧吞吐与请求吞吐分开报，缩批策略的吞吐代价必须显式计入。</li>\n<li>迁移侧：换档位即换参数，不沿用原档位的块大小与重叠窗口。</li>\n</ul>\n<p>具体例子：在 NVL72 形态下，显存容量允许更大的 B 与更大的重叠窗口，缓存复用命中率上升，块间间隔的尾部更平稳；但同一策略搬到单卡档位时，B 被压到很小，重叠窗口被迫收缩，重复前向占比上升，块间间隔的尾部拉长。此时若沿用机架档位的“时延缩短”结论做单卡容量规划，就会系统性低估显存与带宽压力——这正是口径框架要挡住的那类错误。</p>\n<p>最终落在一条工程判断上：这篇论文的基准价值不在数字，而在它把视频扩散推理的代价拆成了块级激活、块级 KV、VAE 驻留与调度水位四个可分别度量、可分别调节的量；读者拿到任何一组视频扩散推理数字时，先问它动的是哪一个量、在哪个硬件档位、用什么负载四元组测的，再决定是否把它写进容量模型。</p>\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-52\">五十二 · 迁移到非 DiT 主干：缓存契约先于算子移植</h3>\n<p>这套方案能搬走的前提，是目标模型存在“可复用的跨块中间状态”这一结构事实。流式推理把采样按时间块推进，块 b 的注意力计算复用块 b−1 保留的键值与中间特征，本质上要求主干在时间维上具备局部因果或有限感受野，并且键值张量的语义在块边界处保持稳定。换成纯 Transformer 的视频扩散主干，跨块 KV 复用是自然成立的；换成以 3D 卷积或隐式神经表示为骨架的生成器，所谓“缓存”就退化为特征图拼接，复用带来的计算节省立刻缩水，因为卷积核在块边界处需要 halo 区域，重叠窗口被迫放大，重复计算的比例随之上升。</p>\n<p>迁移时的第一个动作不是改算子，而是写清楚缓存契约：哪些张量跨块存活、生命周期多长、块边界处是否需要重新归一化。伪代码层面可以写成一条不变式——对任意块 b，其注意力输入只依赖 <span>KV<sub>b−1</sub></span> 的尾部窗口与本块激活，任何破坏该不变式的模型改动都必须触发缓存失效。工程代价体现在显存上：契约越宽，常驻缓存越大，<span>Mem<sub>peak</sub></span> 中 <span>KV<sub>b</sub></span> 项就越难压缩；契约越窄，复用率越低，时延收益被重叠计算吃掉。判断标准很直接：若目标模型的跨块状态维度超过块内激活的量级，这套流式方案的经济性就不成立。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-53\">五十三 · 精度与算子：跨档位迁移要重做验证矩阵</h3>\n<p>论文把精度策略围绕算子数值格式与 KV 缓存占用展开，但没有给出具体量化方案，也没有验证跨硬件档位的可移植性。这意味着迁移到另一档 Blackwell 配置（例如从单机 NVL72 机架内的紧耦合域走到跨节点域）时，NVFP4/FP8 的收益不能按比例外推。低精度算子对时空注意力的数值稳定性敏感：跨块复用的键值一旦被量化，误差会沿时间轴累积，块 b 的复用缓存携带的是块 b−1 的量化残差，长视频下这种累积比单块内量化更危险。</p>\n<p>可操作的迁移做法是建立二维验证矩阵：行是数值格式（FP8、NVFP4、混合），列是块大小与重叠窗口，每个格子记录峰值显存与块间等待时间两个指标，而不是只看端到端时延。原因是流式管线的 SLO 由块间等待时间刻画，端到端数字会把块间抖动平均掉。代价判断上，若某个格式组合使块间等待时间的方差超过均值的一个可观比例，即便平均时延更好也不应上线，因为流式输出的连续性会被破坏。这里没有数字可引，判断只能落在机制上：量化误差随复用链长度增长，复用链长度由块数与重叠决定，因此精度选择必须与分块策略联合调参，不能各自独立最优。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-54\">五十四 · 领域迁移：长时序、强交互、实时闭环三类场景的适配度</h3>\n<p>把流式分块采样搬到别的领域，适配度取决于该领域对“块边界连续性”的容忍度。第一类是长时序生成（长视频、时序预测可视化），块间重叠与缓存复用天然契合，因为输出本身就是顺序消费的，流式解码与流式输出同构，迁移成本主要在 VAE 解码模块的按块切分上。第二类是强交互场景（视频编辑、可控生成），编辑信号往往要求全局一致性，跨块缓存携带的是旧条件，条件变更时必须整链失效，缓存命中率骤降，此时流式方案的显存收益仍在但时延收益消失，需要退化为更小的块与更大的重叠。第三类是实时闭环（在线感知回灌、仿真渲染），SLO 以块间等待时间的上界衡量，调度器按显存水位缩批的策略会与闭环的固定节拍冲突，缩批带来的吞吐下降直接表现为节拍丢失。</p>\n<p>三类场景的共同代价项是块间等待：它不进入 <span>Mem<sub>peak</sub></span> 公式，却决定系统能否上线。迁移判断可以写成一句话——若目标领域的输出消费者不能容忍块粒度的时间抖动，这套方案只能取其缓存复用部分，放弃流式推进的调度形态。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-55\">五十五 · 规模上限：块数与复用链长度的双重约束</h3>\n<p>规模上限不在单块算力，而在复用链的可维护性。峰值显存公式 <span>Mem<sub>peak</sub> ≈ Σ<sub>b</sub>(Act<sub>b</sub> + KV<sub>b</sub>) + VAE<sub>dec</sub></span> 中，求和上界 B 是块数，随视频时长线性增长；即便每块完成后释放缓存，调度器仍需保留跨块键值窗口与未解码块的中间特征，常驻部分随 B 增长而增长，只是斜率被压低。真正的上限出现在两个地方：一是重叠窗口占比，重叠越大重复计算越多，总算力随 B 超线性上升；二是复用链长度，链越长量化误差与数值漂移累积越明显，精度回退（更小分块或更低精度）的频率越高，而回退本身会打断流式节拍。</p>\n<p>因此规模上限应表述为“在给定显存档位与 SLO 抖动容忍度下，可维持稳定块间等待的最大 B”。工程上要测的是 B 增大时块间等待时间的分布尾部，而不是平均值。若尾部随 B 单调恶化且无平台，说明调度器的缩批策略已到极限，继续加长视频只能靠增加硬件档位或降低输出帧率，而不是靠调块大小。这条判断对容量规划直接有用：长视频部署的扩容点不在算力峰值，而在缓存常驻与抖动尾部。</p>\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-56\">五十六 · 不适用的边界与回退路径</h3>\n<p>明确不适用的情况有三类。其一，模型没有时间维可分块的结构，例如单帧图像扩散或全局注意力贯穿整段序列的架构，分块会切断全局依赖，输出质量不可接受，此时流式方案只剩 VAE 分块解码可用。其二，请求本身就是短序列、低并发的离线批处理，块间重叠的重复计算无法被缓存复用摊薄，直接整段前向的显存虽高但时延更优，流式反而增加调度开销。其三，硬件档位不支持所需的低精度算子，精度策略退化为高精度后，<span>KV<sub>b</sub></span> 占用上升，块大小被迫缩小，重叠占比上升，收益链条断裂。</p>\n<p>回退路径要预先写进调度器而不是事后补：显存水位越线时先缩批、再增重叠、最后降精度，三级回退的触发阈值必须与块间等待时间的监控绑定。论文材料未给出具体阈值与监控指标，这正是迁移时最需要补齐的部分——没有阈值，回退策略在并发升高时无法稳定触发，SLO 抖动只能靠人工干预。判断落在机制上：流式推理的可迁移性不取决于算子移植的难度，而取决于目标系统是否愿意为块粒度的时间语义付出调度复杂度；不愿意，就不要用这套方案。</p>\n\n\n<h3 id=\"paper-fast-and-memory-efficient-video-diff-2024-sec-57\">五十七 · 迁移边界：什么能搬、什么必须重算、上限卡在哪</h3>\n<p>这套方案真正可迁移的内核只有两条：按时间块推进采样，以及跨块复用键值与中间特征。凡是“序列在时间维上可切、块间依赖可由缓存承载”的扩散或流匹配推理，机制都能直接搬；一旦模型的时间维不可切分（例如全局时空注意力在每一层都做全序列耦合，或采样器本身要求整段潜变量同时在场做归一化），分块就退化为近似，缓存复用的收益被“块边界处重新对齐”的开销吃掉。判断标准应落在注意力感受野上：若单块的跨块注意力窗口长度与块大小同量级，缓存命中率高；若窗口远大于块，跨块键值复用率下降，重复前向重新出现。迁移到图像扩散或单帧生成时，时间维退化为批维，缓存复用让位于批内共享，收益主要来自 VAE 解码分块而非采样分块，此时应把调度器重心从“重叠窗口”转到“批粒度与显存水位”。</p>\n<p>失效条件集中在三处。其一是重叠窗口的重复计算：设块大小 <span class=\"inline-math\">$L$</span>、重叠 <span class=\"inline-math\">$O$</span>，重复计算比例近似为 <span class=\"inline-math\">$O/(L-O)$</span>，当 <span class=\"inline-math\">$O$</span> 逼近 <span class=\"inline-math\">$L/2$</span> 时有效算力被浪费近一半，而缩小 <span class=\"inline-math\">$O$</span> 又会在块边界引入接缝与缓存失配——这是该方案最本质的时延与质量权衡，长视频下容易被低估。其二是流式输出对批调度的敏感性：调度器按显存水位缩批，块间等待时间随并发上升而抖动，SLO 稳定性缺乏数字支撑，工程上必须把“块间等待”而非平均时延作为主监控量。其三是精度与显存策略的可移植性：数值格式收益依赖 Blackwell 档位的算子支持，换到算子覆盖不全的档位或非 NVIDIA 后端，低精度路径可能退化为软件模拟，带宽节省消失而时延反升，跨档位迁移必须重新做算子级验证而非照搬配置。</p>\n<table class=\"mini\"><thead><tr><th>迁移目标</th><th>可直接复用</th><th>必须重做</th><th>主要代价</th></tr></thead><tbody><tr><td>同类视频扩散/流匹配</td><td>分块调度、跨块 KV 与特征缓存</td><td>块大小与重叠标定</td><td>重叠重复计算、块间等待</td></tr><tr><td>图像/单帧扩散</td><td>VAE 分块解码、显存水位调度</td><td>缓存维度从时间转批</td><td>批调度抖动、缓存命中下降</td></tr><tr><td>全局时空耦合模型</td><td>仅 VAE 流式解码</td><td>采样分块需改近似策略</td><td>接缝质量、重复前向回升</td></tr><tr><td>非 Blackwell 后端</td><td>调度与缓存逻辑</td><td>精度路径与算子验证</td><td>低精度收益丢失、带宽回升</td></tr></tbody></table>\n<p>规模上限由峰值显存公式给出方向：<span class=\"formula\">$$\\mathrm{Mem}_{\\mathrm{peak}} \\approx \\sum_{b=1}^{B}\\big(\\mathrm{Act}_{b}+\\mathrm{KV}_{b}\\big)+\\mathrm{VAE}_{\\mathrm{dec}}$$</span> 其中 <span class=\"inline-math\">$B$</span> 是同时在场的块数。方案把 <span class=\"inline-math\">$B$</span> 压到很小以控制峰值，但块数越多、块越小，跨块缓存管理与调度开销占比越高，块间等待累积成主导时延；反过来放大块会推高 <span class=\"inline-math\">$\\mathrm{Act}_{b}$</span> 与 <span class=\"inline-math\">$\\mathrm{KV}_{b}$</span>，逼近部署档位上限。因此上限不是“能跑多长视频”，而是“在给定显存档位下，块大小与重叠能把重复计算比例与块间等待同时压在 SLO 内”的那个工作点；超出该点应改用分离式预填/解码或降低分辨率与帧率，而不是继续调重叠。工程判断：先把块间等待与重复计算比例做成两个可观测指标，再决定是否迁移；缺这两项监控时，任何跨模型移植都只是配置搬运。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Fast and Memory-Efficient </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Video Diffusi…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2024 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Fast and Memory-Efficie… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>未给出</td></tr><tr><td>基线</td><td>未给出</td></tr><tr><td>主要结果</td><td>论文报告流式推理在视频扩散采样中降低峰值显存并缩短时延，具体数据集与基线数…</td></tr><tr><td>消融</td><td>消融围绕块大小、重叠窗口与缓存复用策略展开，考察峰值显存与采样时延的权衡；…</td></tr><tr><td>局限</td><td>长视频分块与重叠引入块间等待与重复计算，流式输出对批调度敏感；精度与显存策…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-fast-and-memory-efficient-video-diff-2024 · 共 9 个片段</p>\n";break;}}})();
